function isSprintDiscipline(d){return /^(M|W)(100|200|400)$/.test(String(d||''))}
function sprintCloseMargin(d){const n=DISCIPLINES[d]?.distance||Number(String(d||'').match(/(100|200|400)/)?.[1])||100;return n>=400?.55:n>=200?.28:.15}
function sprintGoodMargin(d){const n=DISCIPLINES[d]?.distance||Number(String(d||'').match(/(100|200|400)/)?.[1])||100;return n>=400?.75:n>=200?.34:.15}
