function drawActivities(){const l=leagueState(),squad=managedTeam();$(currentView==='league'?'league':currentView==='training'?'training':'activities').innerHTML=`<div class="section-head"><div><h2>${activityTab==='league'?'League Events':'Training Camps'}</h2><p>Plan camps and other commitments around the competition calendar.</p></div><span class="status">${money(s.funding)} available</span></div><section class="panel ${activityTab==='camps'?'':'hidden'}"><div class="panel-h"><strong>Specialist Training Camps</strong><span>Upfront cost · gains on completion</span></div><div class="panel-body"><p>Camp athletes cannot compete or take normal weekly training. Camps cannot cross the season boundary. Injury or retirement interrupts a camp without a refund. Development remains limited by the athlete’s hidden ceiling; staff only see a Development Grade that can be revised over time.</p><div class="staff-grid">${Object.entries(CAMP_OPTIONS).map(([k,c])=>`<div class="staff-card"><h3>${c.name}</h3><p>${c.desc}</p><strong>${money(c.cost)} · ${c.weeks} weeks</strong></div>`).join('')}</div>${squad.map(a=>`<div class="staff-card"><strong>${athleteLink(a)}</strong><p>${a.camp?activityLabel(a):health(a)[0]} · Ability ${assessmentText(a,'overall')} / Development ${developmentGradeText(a)}</p>${a.camp?'':`<label>Camp <select data-camp-choice="${a.id}">${Object.entries(CAMP_OPTIONS).map(([k,c])=>`<option value="${k}">${c.name} · ${money(c.cost)}</option>`).join('')}</select></label><div data-camp-preview="${a.id}"></div><button class="btn secondary" data-send-camp="${a.id}" ${a.injury>0?'disabled':''}>BOOK CAMP & WITHDRAW CONFLICTING ENTRIES</button>`}</div>`).join('')}</div></section><section class="panel ${activityTab==='league'?'':'hidden'}"><div class="panel-h"><strong>National League Circuit</strong><span>Weeks 16–21 · rounds 17 / 19 / 21</span></div><div class="panel-body"><p>Maximum two squad entries per discipline. Entry is free. Once Week 16 starts you cannot withdraw or enter other competitions through Week 21. Normal training continues between league rounds. No world/Olympic points, records or sponsorship progress.</p><p>Prizes per discipline: £600k / £400k / £250k / £150k / £100k / £75k / £50k / £25k. At least one start required; retired athletes earn no prize. Ties use round wins, then athlete ID. Injury means missing that round.</p>${squad.map(a=>{const entered=l.entries.includes(a.id),miss=commitmentConflicts(a,16,21);return `<div class="staff-card"><strong>${athleteLink(a)}</strong><p>${entered?'Entered':'Not entered'} · Conflicting opportunities: ${miss.join(', ')||'None in the current calendar'}</p><button class="btn secondary" data-league="${a.id}" ${s.game.week>=16||!entered&&(a.injury>0||l.entries.filter(id=>s.athletes.find(x=>x.id===id)?.disc===a.disc).length>=2||a.camp&&a.camp.until>careerNow()+16-s.game.week)?'disabled':''}>${s.game.week>=16?'ENTRIES CLOSED':entered?'WITHDRAW BEFORE DEADLINE':'ENTER LEAGUE'}</button></div>`}).join('')}${l.settled?`<h3>Prize money received: ${money(l.payout)}</h3>`:''}${Object.keys(l.fields).map(d=>`<h3>${discLabel(d)}</h3><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>Athlete</th><th>League points</th><th>Starts</th><th>Marks by round</th></tr></thead><tbody>${leagueStandings(d).map((r,i)=>{const a=s.athletes.find(a=>a.id===r.id);return `<tr><td>${i+1}</td><td>${a?athleteLink(a):'Former athlete'}</td><td>${r.points}</td><td>${r.starts}</td><td>${[17,19,21].map(w=>{const x=l.rounds[w]?.[d]?.find(x=>x.id===r.id);return 'W'+w+': '+(x?fmtPerf(d,x.perf):l.rounds[w]?'DNS':'—')}).join(' · ')}</td></tr>`}).join('')}</tbody></table></div>`).join('')}</div></section>`;document.querySelectorAll('[data-activity-tab]').forEach(b=>b.onclick=()=>{activityTab=b.dataset.activityTab;drawActivities()});document.querySelectorAll('[data-camp-choice]').forEach(sel=>{sel.onchange=()=>{const a=s.athletes.find(a=>a.id===sel.dataset.campChoice),c=CAMP_OPTIONS[sel.value],end=s.game.week+c.weeks-1,miss=commitmentConflicts(a,s.game.week,end);document.querySelector('[data-camp-preview="'+a.id+'"]').textContent='Away W'+s.game.week+'–W'+end+'. '+c.desc+' Cost '+money(c.cost)+'. Budget after '+money(s.funding-c.cost)+'. Missed opportunities: '+(miss.join(', ')||'None');const league=s.leagues?.[s.game.season],button=document.querySelector('[data-send-camp="'+a.id+'"]');button.disabled=a.injury>0||s.funding<c.cost||end>52||!!(league?.entries.includes(a.id)&&s.game.week<=21&&end>=16)};sel.onchange()});document.querySelectorAll('[data-send-camp]').forEach(b=>b.onclick=()=>sendToCamp(b.dataset.sendCamp,document.querySelector('[data-camp-choice="'+b.dataset.sendCamp+'"]').value));document.querySelectorAll('[data-league]').forEach(b=>b.onclick=()=>l.entries.includes(b.dataset.league)?withdrawLeague(b.dataset.league):enterLeague(b.dataset.league))}
function health(a){if(!a.retired&&activityLabel(a))return[activityLabel(a),'warn'];if(a.retired)return['Retired',''];if(a.injury>0)return['Injured','bad'];if(a.fatigue>=80)return['Critical','bad'];if(a.fatigue>=60)return['Tired','warn'];if(a.fitness>=90&&a.form>=82)return['Ready','good'];return['Available','']}
function managedNation(){return s?.managedNation||'GREAT BRITAIN'} function nationName(n){return COUNTRIES[n]?.name||n} function nationProfile(n=managedNation()){return NATIONS[n]||NATIONS['GREAT BRITAIN']}
function nationalIdentityBlueprint(n=managedNation()){return NATIONAL_IDENTITY_BLUEPRINTS[n]||NATIONAL_IDENTITY_BLUEPRINTS['GREAT BRITAIN']}
function ensureNationalIdentities(){s.nationalIdentities??={};for(const n of Object.keys(NATIONS))s.nationalIdentities[n]??=initialNationalIdentity(n);return s.nationalIdentities}
function nationalIdentityState(n=managedNation()){ensureNationalIdentities();return s.nationalIdentities[n]||initialNationalIdentity(n)}
function nationalIdentityDirection(n=managedNation()){const st=nationalIdentityState(n),gap=st.sprint-st.field;if(gap>=16)return 'Sprint-led';if(gap<=-16)return 'Field-led';return 'Balanced'}
function nationalIdentityLabel(n=managedNation()){const st=nationalIdentityState(n),dir=nationalIdentityDirection(n);return st.pathway>=82?dir+' • Pathway strong':st.pathway<=55?dir+' • Pathway rebuilding':dir}
function identityDisciplineStrength(n,d){const st=nationalIdentityState(n);return isSprintDiscipline(d)?st.sprint:st.field}
function identityDisciplineChoice(n){const st=nationalIdentityState(n),weights=Object.keys(DISCIPLINES).map(d=>[d,Math.max(15,isSprintDiscipline(d)?st.sprint:st.field)]),total=weights.reduce((t,[,w])=>t+w,0);let roll=Math.random()*total;for(const [d,w] of weights){roll-=w;if(roll<=0)return d}return weights[0][0]}
function identityProspectModifier(n,d){const st=nationalIdentityState(n),event=identityDisciplineStrength(n,d),quality=Math.round((event-62)/18),pathway=Math.round((st.pathway-65)/22);return {ability:clamp(quality,-2,2),potential:clamp(pathway,-2,2)}}
function nationalIdentityMetersHTML(n=managedNation()){const st=nationalIdentityState(n);return `<div class="identity-meters">${[['Sprint',st.sprint],['Field',st.field],['Pathway',st.pathway]].map(([k,v])=>`<div class="identity-meter"><span>${k}</span><i><b style="width:${v}%"></b></i><strong>${v}</strong></div>`).join('')}</div>`}
function nationalIdentityHTML(){const n=managedNation(),b=nationalIdentityBlueprint(n),st=nationalIdentityState(n),setup=nationStartingSetup(n);return `<section class="panel"><div class="panel-h"><strong>National Programme Identity</strong><span>${profileEscape(nationalIdentityLabel(n))}</span></div><div class="panel-body"><div class="identity-summary"><div class="identity-card"><span class="identity-tag">${flag(n)} ${profileEscape(b.title.toUpperCase())}</span><h3>${profileEscape(b.culture)}</h3><p>This is a living programme profile, not a permanent national bonus. Facilities, coaching, pathway work and the athletes your system produces gradually change it over long careers.</p>${nationalIdentityMetersHTML(n)}</div><div class="identity-card"><span class="identity-tag">FEDERATION PRIORITY</span><div class="identity-priorities"><div><small>CURRENT REMIT</small><strong>${profileEscape(b.board.priority)}</strong></div><div><small>ANNUAL CORE GRANT</small><strong>${money(setup.annualGrant)}</strong></div><div><small>HERITAGE / CURRENT</small><strong>${profileEscape(b.title)} → ${profileEscape(nationalIdentityDirection(n))}</strong></div></div></div></div></div></section>`}
function evolveNationalIdentitiesAnnual(){ensureNationalIdentities();for(const n of Object.keys(NATIONS)){const st=nationalIdentityState(n);let sprintTarget,fieldTarget,pathwayTarget;if(n===managedNation()){const sprintAth=managedNationAthletes().filter(a=>isSprintDiscipline(a.disc)).sort((a,b)=>b.overall-a.overall).slice(0,4),fieldAth=managedNationAthletes().filter(a=>!isSprintDiscipline(a.disc)).sort((a,b)=>b.overall-a.overall).slice(0,6),avg=(arr,fallback)=>arr.length?arr.reduce((t,a)=>t+a.overall,0)/arr.length:fallback;sprintTarget=clamp(28+facilityLevel('sprint')*9+(s.staff.sprint||1)*4+(avg(sprintAth,70)-65)*.35,30,96);fieldTarget=clamp(28+facilityLevel('field')*9+((s.staff.jumps||1)+(s.staff.throws||1))*2+(avg(fieldAth,70)-65)*.35,30,96);pathwayTarget=clamp(35+(s.staff.scout||1)*8+Math.min(18,(immersionState().board?.prospects?.length||0)*5),30,96)}else{const athletes=s.athletes.filter(a=>!a.retired&&a.nation===n),top=(arr,count)=>{arr=[...arr].sort((a,b)=>b.overall-a.overall).slice(0,count);return arr.length?arr.reduce((t,a)=>t+a.overall,0)/arr.length:60},young=athletes.filter(a=>a.age<=23);sprintTarget=clamp(35+(top(athletes.filter(a=>isSprintDiscipline(a.disc)),4)-60)*1.35,30,96);fieldTarget=clamp(35+(top(athletes.filter(a=>!isSprintDiscipline(a.disc)),6)-60)*1.35,30,96);pathwayTarget=clamp(45+(top(young,5)-60)*1.05,30,96)}st.sprint=Math.round(st.sprint*.78+sprintTarget*.22);st.field=Math.round(st.field*.78+fieldTarget*.22);st.pathway=Math.round(st.pathway*.82+pathwayTarget*.18);st.lastSeason=s.game.season}}
 function managedNationAthletes(){return s.athletes.filter(a=>!a.retired&&a.nation===managedNation())} function managedTeam(){return s.athletes.filter(a=>!a.retired&&a.nation===managedNation()&&a.inSquad!==false)} function nationalPool(){return s.athletes.filter(a=>!a.retired&&a.nation===managedNation()&&a.inSquad===false)} function teamGB(){return managedTeam()} function sender(kind){let p=nationProfile(),i=INTRO_DATA[managedNation()];if(kind==='board'&&i)return `${i.chair} • ${i.chairTitle}`;return p[kind]||p.federation}

const CAREER_MAX_YEARS=40,CAREER_MAX_CYCLES=10;
const OLYMPIC_HOSTS=['Los Angeles','Brisbane','Berlin','Tokyo','Paris','Cape Town','Rome','Toronto','Sydney','London'];
function careerState(){
 const inferred=Math.max(1,Math.min(CAREER_MAX_YEARS,(Number(s?.game?.season)||2027)-2027+1));
 if(!s.career){const cy=Math.floor((inferred-1)/4)+1;s.career={careerYear:inferred,cycleNumber:cy,maxYears:CAREER_MAX_YEARS,maxCycles:CAREER_MAX_CYCLES,seasonHistory:[],completedCycles:[],pendingReview:null,finished:false,nationsManaged:[managedNation()],tenures:[{nation:managedNation(),startSeason:(s.game.season||2027)-((s.game.cycleYear||1)-1),startCareerYear:inferred-((s.game.cycleYear||1)-1)}],nationBudgets:{},nationAssets:{},medalBaseline:{g:0,s:0,b:0},fundingMedalBaseline:{g:0,s:0,b:0}}}
 const c=s.career;c.maxYears=CAREER_MAX_YEARS;c.maxCycles=CAREER_MAX_CYCLES;c.careerYear=Math.max(1,Math.min(CAREER_MAX_YEARS,Number(c.careerYear)||inferred));c.cycleNumber=Math.max(1,Math.min(CAREER_MAX_CYCLES,Number(c.cycleNumber)||Math.floor((c.careerYear-1)/4)+1));c.seasonHistory??=[];c.completedCycles??=[];c.nationsManaged??=[managedNation()];if(!c.nationsManaged.includes(managedNation()))c.nationsManaged.push(managedNation());c.tenures??=[{nation:managedNation(),startSeason:(s.game.season||2027)-((s.game.cycleYear||1)-1),startCareerYear:c.careerYear-((s.game.cycleYear||1)-1)}];c.nationBudgets??={};c.nationAssets??={};c.medalBaseline??={g:0,s:0,b:0};c.fundingMedalBaseline??={g:0,s:0,b:0};c.finished=!!c.finished;return c
}
function olympicHostForCycle(n=careerState().cycleNumber){return OLYMPIC_HOSTS[(Math.max(1,n)-1)%OLYMPIC_HOSTS.length]}
function careerLabel(){const c=careerState();return `Career Year ${c.careerYear}/${CAREER_MAX_YEARS} • Olympic Cycle ${c.cycleNumber}/${CAREER_MAX_CYCLES} • Year ${s.game.cycleYear}/4`}
function seasonMedalDelta(base){base=base||{g:0,s:0,b:0};return {g:Math.max(0,(s.medals.g||0)-(base.g||0)),s:Math.max(0,(s.medals.s||0)-(base.s||0)),b:Math.max(0,(s.medals.b||0)-(base.b||0))}}
function recordCareerSeason(rank,bonus){const c=careerState(),b=immersionState().board,records=(s.performances||[]).filter(p=>p.season===s.game.season&&p.nation===managedNation()&&(p.achievements||[]).some(x=>x==='WR'||x==='NR')).length,summary={season:s.game.season,careerYear:c.careerYear,cycleNumber:c.cycleNumber,cycleYear:s.game.cycleYear,nation:managedNation(),rank,bonus,youngInternationals:b?.prospects?.length||0,targetProspects:b?.targetProspects||2,records};c.seasonHistory.push(summary);if(c.seasonHistory.length>CAREER_MAX_YEARS)c.seasonHistory=c.seasonHistory.slice(-CAREER_MAX_YEARS);return summary}
function buildCycleReview(){const c=careerState(),cycle=c.cycleNumber,nation=managedNation(),years=c.seasonHistory.filter(x=>x.cycleNumber===cycle&&x.nation===nation).slice(-4),medals=seasonMedalDelta(c.medalBaseline),avgRank=years.length?years.reduce((t,x)=>t+x.rank,0)/years.length:8,bestRank=years.length?Math.min(...years.map(x=>x.rank)):8,pathway=years.length?years.reduce((t,x)=>t+Math.min(1,x.youngInternationals/Math.max(1,x.targetProspects)),0)/years.length:0,records=years.reduce((t,x)=>t+x.records,0),rankScore=Math.max(0,40-(avgRank-1)*6),medalScore=medals.g*20+medals.s*13+medals.b*8,pathwayScore=pathway*12,recordScore=Math.min(10,records*2),score=Math.round(clamp(rankScore+medalScore+pathwayScore+recordScore,0,100)),expectation=nationProfile(nation).expectation,threshold=expectation==='Very High'?50:expectation==='High'?43:36,renewed=score>=threshold,verdict=score>=78?'Exceptional':score>=62?'Strong':renewed?'Board satisfied':'Below expectation',others=Object.keys(NATIONS).filter(n=>n!==nation).sort((a,b)=>(hashString(`${cycle}:${b}:${score}`)%100)-(hashString(`${cycle}:${a}:${score}`)%100)),offerCount=score>=72?3:2,offers=others.slice(0,offerCount);return {cycle,nation,startSeason:s.game.season-3,endSeason:s.game.season,score,threshold,renewed,verdict,medals,avgRank:+avgRank.toFixed(1),bestRank,pathway:+pathway.toFixed(2),records,offers}}
function prepareNationForManagement(nation,firstAppointment=false){
 let own=s.athletes.filter(a=>!a.retired&&a.nation===nation);if(firstAppointment){const chosen=[];for(const d of Object.keys(DISCIPLINES)){const a=own.filter(a=>a.disc===d).sort((a,b)=>performanceScore(b)-performanceScore(a))[0];if(a&&!chosen.includes(a.id))chosen.push(a.id)}for(const a of [...own].sort((a,b)=>performanceScore(b)-performanceScore(a)))if(chosen.length<7&&!chosen.includes(a.id))chosen.push(a.id);own.forEach(a=>a.inSquad=chosen.includes(a.id))}
 const ids=new Set(s.athletes.map(a=>a.id));if(!s.athletes.some(a=>!a.retired&&a.nation===nation&&a.inSquad===false))s.athletes.push(...makeInitialPool(nation).filter(a=>!ids.has(a.id)));hydrateVisualIdentity(s)
}
function acceptCareerJob(nation){const c=careerState(),r=c.pendingReview;if(!r||!NATIONS[nation])return;const old=managedNation(),moving=nation!==old,seen=c.nationsManaged.includes(nation);if(moving){c.nationBudgets[old]=s.funding;c.nationAssets[old]={funding:s.funding,facilityLevels:s.facilityLevels?{...s.facilityLevels}:null,facilities:s.facilities||1,facilityHistory:[...(s.facilityHistory||[])],annualSpend:s.annualSpend||0};const tenure=c.tenures[c.tenures.length-1];if(tenure&&!tenure.endSeason)tenure.endSeason=r.endSeason;c.nationsManaged.push(...(seen?[]:[nation]));c.tenures.push({nation,startSeason:s.game.season,startCareerYear:c.careerYear});s.managedNation=nation;const asset=c.nationAssets[nation];if(asset){s.funding=asset.funding;s.facilityLevels=asset.facilityLevels?{...asset.facilityLevels}:undefined;s.facilities=asset.facilities||1;s.facilityHistory=[...(asset.facilityHistory||[])];s.annualSpend=asset.annualSpend||0}else{const setup=nationStartingSetup(nation);s.funding=setup.funding;s.facilityLevels={...setup.facilities};s.facilities=1;s.facilityHistory=[];s.annualSpend=0}prepareNationForManagement(nation,!seen);Object.values(s.coaches||{}).forEach(coach=>recordCoachMove(coach,`Moved with the performance leadership team to ${nationName(nation)}.`))}
 c.completedCycles.push({...r,acceptedNation:nation});c.pendingReview=null;c.medalBaseline={...s.medals};c.fundingMedalBaseline={...s.medals};s.game.cycleYear=1;s.events=makeEvents(1,nation,c.cycleNumber);s.immersion=s.immersion||{};s.immersion.board=null;immersionState();weeklyLifecycle();const p=nationProfile(nation),i=INTRO_DATA[nation];if(moving){newMail(`${i.chair} • ${i.chairTitle}`,`Appointment confirmed: ${p.name}`,`Your appointment as Performance Director begins immediately. Career Year ${c.careerYear} starts a new Olympic cycle. The athletes, records and wider athletics world continue from your existing career.`,'contract');addNews('Federation',`${p.name} appoint new Performance Director`,`A change of national programme begins at the start of Olympic Cycle ${c.cycleNumber}.`,`The new Performance Director arrives after completing the previous Olympic cycle with ${nationName(old)}. The wider athletics world, athlete careers and records continue unchanged.`,{nation,priority:'major'})}else newMail(sender('board'),`Contract renewed: Olympic Cycle ${c.cycleNumber}`,`The federation has renewed your appointment for another four-year Olympic cycle. Career Year ${c.careerYear} begins with ${p.name}.`,'review');const el=$('managementProfile');if(el?.open)el.close();if(el)el.oncancel=null;applyNationTheme();save();render();view('home');toast(moving?`New job: ${p.name}`:`Contract renewed`)
}
function openCycleReview(){const c=careerState(),r=c.pendingReview;if(!r)return;const p=NATIONS[r.nation],el=$('managementProfile'),medals=r.medals.g+r.medals.s+r.medals.b;el.innerHTML=`<div class="profile-shell"><header class="profile-top"><div><small>OLYMPIC CYCLE REVIEW</small><span>Cycle ${r.cycle} complete • ${r.startSeason}–${r.endSeason}</span></div></header><main class="profile-body"><section class="profile-hero"><div class="profile-identity"><div class="profile-kicker">${p.flag} ${profileEscape(p.name)} • BOARD REVIEW</div><h1 id="managementName">${profileEscape(r.verdict)} cycle</h1><p>The four-year contract has reached its review point. Your career continues; the decision is whether the next cycle begins here or with another national programme.</p></div><div class="profile-rating"><small>BOARD SCORE</small><strong>${r.score}</strong><span>Renewal line ${r.threshold}</span></div></section><div class="profile-headline-stats"><div class="profile-metric"><small>Olympic medals</small><strong>${medals}</strong><span>${r.medals.g} gold • ${r.medals.s} silver • ${r.medals.b} bronze</span></div><div class="profile-metric"><small>Average nation rank</small><strong>#${r.avgRank}</strong><span>Best finish #${r.bestRank}</span></div><div class="profile-metric"><small>Pathway delivery</small><strong>${Math.round(r.pathway*100)}%</strong><span>Young-athlete objective delivery</span></div><div class="profile-metric"><small>Records</small><strong>${r.records}</strong><span>National/world records during the cycle</span></div></div><section class="profile-panel"><h2>${r.renewed?'Renewal offered':'Contract not renewed'}</h2><p>${r.renewed?`${p.federation} is offering you another four-year term. Accepting keeps you in charge for Olympic Cycle ${c.cycleNumber}.`:`${p.federation} has decided to make a change after the cycle review. Your management career is not over: other national programmes have made approaches.`}</p>${r.renewed?`<button class="btn primary" data-career-job="${r.nation}">RENEW WITH ${profileEscape(p.name.toUpperCase())}</button>`:''}</section><section class="profile-panel"><h2>National job market</h2><p>These are formal approaches for the next Olympic cycle. Taking one changes the programme you control, not the world itself: athletes, records, rivalries and history all continue.</p><div class="staff-grid">${r.offers.map(n=>{const x=NATIONS[n];return `<div class="staff-card"><h3>${x.flag} ${profileEscape(x.name)}</h3><p>${profileEscape(x.profile)}<br><strong>Programme:</strong> ${profileEscape(nationalIdentityBlueprint(n).title)}<br><strong>Expectation:</strong> ${profileEscape(x.expectation)}</p><button class="btn secondary" data-career-job="${n}">ACCEPT ${profileEscape(x.name.toUpperCase())} JOB</button></div>`}).join('')}</div></section><p class="profile-caption">Career Year ${c.careerYear}/${CAREER_MAX_YEARS} • Olympic Cycle ${c.cycleNumber}/${CAREER_MAX_CYCLES}. A decision is required before the next season can begin.</p></main></div>`;el.querySelectorAll('[data-career-job]').forEach(b=>b.onclick=()=>acceptCareerJob(b.dataset.careerJob));el.oncancel=e=>e.preventDefault();if(!el.open)el.showModal()
}
function openCareerLegacy(){const c=careerState(),cycles=c.completedCycles,medals=s.medals.g+s.medals.s+s.medals.b,el=$('managementProfile');managementDialog('Forty-year career complete',`<section class="profile-hero"><div class="profile-identity"><div class="profile-kicker">ATHLETICS MANAGER • CAREER COMPLETE</div><h1>Ten Olympic cycles.</h1><p>Your 40-season management career is complete. The save remains available to review.</p></div><div class="profile-rating"><small>CAREER MEDALS</small><strong>${medals}</strong><span>${s.medals.g}G • ${s.medals.s}S • ${s.medals.b}B</span></div></section><div class="profile-headline-stats"><div class="profile-metric"><small>Career years</small><strong>40</strong></div><div class="profile-metric"><small>Olympic cycles</small><strong>${cycles.length||10}</strong></div><div class="profile-metric"><small>Nations managed</small><strong>${c.nationsManaged.length}</strong></div><div class="profile-metric"><small>Career score</small><strong>${s.game.careerScore||0}</strong></div></div><section class="profile-panel"><h2>Management journey</h2>${c.tenures.map(t=>`<p><strong>${flag(t.nation)} ${profileEscape(nationName(t.nation))}</strong><br>${t.startSeason}${t.endSeason?'–'+t.endSeason:'–'+s.game.season}</p>`).join('')}</section>`)}
function pushMail(st,senderName,subject,body,type='info',eventId=null,html=null,id=null){let mid=id||'m'+Date.now()+Math.random().toString(16).slice(2);st.emails.push({id:mid,sender:senderName,subject,body,html,type,eventId,unread:true,week:st.game.week,year:st.game.cycleYear});return mid}
function seedContractMail(st){let p=NATIONS[st.managedNation],i=INTRO_DATA[st.managedNation];if(!p||!i||st.emails.some(m=>m.type==='contract'))return;pushMail(st,`${i.chair} • ${i.chairTitle}`,`Official appointment: ${p.name} Performance Director`,`On behalf of ${p.federation}, I am pleased to formally offer you responsibility for the national high-performance athletics programme. Please review and sign the appointment contract below before beginning your duties.`,'contract',null,null,'appointment-contract')}
function seedWelcomeMails(){if(!s.appointment||s.appointment.introSeeded)return;const p=nationProfile(),i=INTRO_DATA[managedNation()];pushMail(s,p.performance,'Your programme: a desk reference','Keep this briefing handy as you settle in.','systems',null,`<div class="mail-section"><h3>Prepare, select, compete, review</h3><p>Training sets the weekly direction. Check form, fitness and fatigue together, then adjust individual loads where needed. Read the selection advice before entering athletes and attend events with your squad entered.</p></div><div class="mail-section"><h3>Your squad and your next discovery</h3><p>You have ${SQUAD_LIMIT} squad places. New scouting discoveries join the national pool every eight career weeks, with additional discoveries at scouting events. Make room before calling someone up. Unselected squad athletes do not compete; pool athletes may enter domestic events independently.</p></div><div class="mail-section"><h3>Know the people behind the numbers</h3><p>Tap an athlete to see their profile, results and career moments. Selection conversations and recovery decisions affect your relationship. Young athletes can develop through competition experience.</p></div><div class="mail-section"><h3>Make Home your daily stop</h3><p>The action strip flags decisions. Programme tabs show readiness, weekly changes and board objectives; World tabs keep you connected to rivals. The Calendar holds the full season. Begin with one week and see how your athletes respond.</p></div>`);pushMail(s,`${i.chair} • ${i.chairTitle}`,'Your office is ready, Director','Your appointment is confirmed. The programme is yours.','welcome',null,`<div class="mail-section"><h3>${p.flag} Welcome to ${p.name}</h3><p>${profileEscape(s.managerName||'Director')}, the coaches have your appointment confirmation. Your first task is to get to know the people you are leading.</p><p>${i.history}</p></div><div class="mail-section"><h3>What we are working towards</h3><p>${i.mandate}</p><p>${i.firstTarget}</p></div><div class="mail-section"><h3>Take the first step</h3><p>Your first-day introduction is available from Home. Meet the athletes, choose an opening training approach and advance a week when you are ready. We will send a report on how the squad responds.</p></div>`);s.appointment.introSeeded=true}
function appointmentPending(){return !!(s?.appointment&&!s.appointment.contractSigned)}
function appointmentTask(k){if(!s?.appointment?.contractSigned||!s.appointment.tasks||s.appointment.tasks[k])return;s.appointment.tasks[k]=true;let done=Object.values(s.appointment.tasks).every(Boolean);if(done&&!s.appointment.completed){s.appointment.completed=true;let i=INTRO_DATA[managedNation()];pushMail(s,`${i.chair} • ${i.chairTitle}`,'First 30 days: initial review complete',`Thank you. You have completed the initial programme review. The board now expects you to take ownership of selection, development and results across the remainder of the cycle.`,'review');addNews('Federation',`${nationName(managedNation())} Performance Director completes initial programme review`,`The new national leadership has completed its opening assessment period.`,`The federation has confirmed that the Performance Director has completed the first review of squad, pathway, calendar and training operations. Attention now turns fully to competitive performance.`,{nation:managedNation()})}save()}
function appointmentProgress(){let t=s?.appointment?.tasks||{};return Object.values(t).filter(Boolean).length}
function contractHTML(){let p=nationProfile(),i=INTRO_DATA[managedNation()],signed=s.appointment?.contractSigned;return `<div class="contract-doc"><div class="contract-top"><small>${p.federation} • Official Appointment</small><h3>National Performance Director</h3></div><div class="contract-grid"><div class="contract-line"><small>National Programme</small><strong>${p.flag} ${p.name}</strong></div><div class="contract-line"><small>Contract Term</small><strong>4-year championship cycle</strong></div><div class="contract-line"><small>Starting Performance Budget</small><strong>${money(s.funding)}</strong></div><div class="contract-line"><small>National Squad Limit</small><strong>${SQUAD_LIMIT} athletes</strong></div><div class="contract-line"><small>Board Expectation</small><strong>${p.expectation}</strong></div><div class="contract-line"><small>Primary Objective</small><strong>Olympic performance</strong></div></div><div class="contract-mandate"><strong>Mandate:</strong> ${i.mandate}<br><br><strong>Cycle target:</strong> ${i.firstTarget}</div><div class="contract-sign"><div class="signature">${i.chair}<small>${i.chairTitle} • On behalf of ${p.federation}</small></div>${signed?'<span class="signed-stamp">✓ Appointment Accepted</span>':'<button id="signContract" class="btn primary">SIGN & ACCEPT APPOINTMENT</button>'}</div></div>`}
function signAppointmentContract(){if(!s.appointment||s.appointment.contractSigned)return;s.appointment.contractSigned=true;s.appointment.signedWeek=s.game.week;seedWelcomeMails();save();toast(`Appointment confirmed • ${nationName(managedNation())}`);let welcome=s.emails.find(m=>m.type==='welcome');openMail=welcome?.id||openMail;render();view('inbox');if(firstDayCanOpen()){s.induction.step='people';s.induction.paused=false;save();openFirstDay()}}

function nationRanks(){return Object.entries(s.nationPoints).sort((a,b)=>b[1]-a[1])}
function currentEvent(){return s.events.find(e=>e.week===s.game.week&&!e.completed&&(e.kind==='competition'||e.kind==='championship'||e.kind==='olympics'||e.kind==='testing'))}
function nextEvent(){return s.events.find(e=>!e.completed&&e.week>=s.game.week)||s.events[s.events.length-1]}
function currentBlocking(){let e=currentEvent();return e&&['competition','championship','olympics'].includes(e.kind)?e:null}
function eventEntries(e){if(e.id==='olympics')lockOlympicQualification(e);return Object.values(e.entries||{}).flat()}
function olympicRanking(d){return s.athletes.filter(a=>!a.retired&&a.disc===d&&a.points>0).sort((a,b)=>b.points-a.points||(DISCIPLINES[d].type==='time'?a.pb-b.pb:b.pb-a.pb)||String(a.id).localeCompare(String(b.id)))}
function olympicQualifiers(d){const counts={};return olympicRanking(d).filter(a=>{if(a.injury>0||activityBusy(a,36)||(counts[a.nation]||0)>=2)return false;counts[a.nation]=(counts[a.nation]||0)+1;return true}).slice(0,12)}
function lockOlympicQualification(e){if(!e||e.id!=='olympics'||e.completed||e.qualification||s.game.week<e.week)return;e.qualification={season:s.game.season,week:e.week,fields:{}};e.entries??={};for(const d of e.disc){const existing=e.results?.[d];const field=Array.isArray(existing)?existing.map(x=>s.athletes.find(a=>a.id===x.id)).filter(Boolean):olympicQualifiers(d);e.qualification.fields[d]=field.map(a=>({id:a.id,points:a.points}));e.entries[d]=field.filter(a=>a.nation===managedNation()).map(a=>a.id)}e.decision=true;const own=eventEntries(e).map(id=>s.athletes.find(a=>a.id===id)).filter(Boolean);newMail(sender('olympic'),'Olympic qualification confirmed',`${own.length} athletes have qualified automatically for ${nationName(managedNation())}. ${own.map(a=>a.name+' ('+discLabel(a.disc)+')').join(', ')||'No athletes made the qualifying places.'} The fields are now locked. Injured or retired athletes cannot start; places are not reassigned after the deadline. Open the Olympic screen to review the fields.`,'info');save()}
function olympicField(e,d){lockOlympicQualification(e);const rows=e.qualification?.fields[d];return rows?rows.map(x=>s.athletes.find(a=>a.id===x.id)).filter(a=>a&&!a.retired&&a.injury===0&&!activityBusy(a,e.week)):olympicQualifiers(d)}
function olympicRules(){return 'Automatic qualification: 12 available athletes per discipline, maximum two per nation, ranked by current-season points (at least one point). Ties use personal best, then athlete ID. Injured and retired athletes are excluded at the Week 36 deadline in Year 4. National-pool athletes can qualify. Places are provisional until the deadline; no replacements afterwards.'}
function eligibleFor(e,d){if(e.id==='olympics')return olympicField(e,d).filter(a=>a.nation===managedNation());return teamGB().filter(a=>{if(a.disc!==d||a.injury>0||activityBusy(a,e.week))return false;if(e.elite&&performanceScore(a)<64)return false;if(e.qualified&&e.id!=='olympics'&&!(a.points>=6||performanceScore(a)>=64))return false;return true})}

function better(d,a,b){if(b==null)return true;return DISCIPLINES[d].type==='time'?a<b:a>b}
function initWorldRecords(st){let nat={};Object.keys(COUNTRIES).forEach(n=>{nat[n]={};Object.keys(DISCIPLINES).forEach(d=>{let xs=st.athletes.filter(a=>a.nation===n&&a.disc===d).map(a=>a.pb);if(xs.length){let best=DISCIPLINES[d].type==='time'?Math.min(...xs):Math.max(...xs);let buffer=DISCIPLINES[d].type==='time'?.04:DISCIPLINES[d].type==='height'?.03:.45;nat[n][d]={value:+(DISCIPLINES[d].type==='time'?best-buffer:best+buffer).toFixed(2),holder:'Historic benchmark',season:'Pre-career'}}})});st.records={world:Object.fromEntries(Object.entries(WORLD_RECORDS).map(([d,v])=>[d,{value:v,holder:'World Record',nation:'WORLD',season:'Pre-career'}])),national:nat}}
function pushNews(st,category,headline,deck,body,opts={}){let n={id:'n'+Date.now()+Math.random().toString(16).slice(2),season:st.game.season,week:st.game.week,category,headline,deck:deck||'',body:body||deck||'',priority:opts.priority||'normal',nation:opts.nation||null,athleteId:opts.athleteId||null,event:opts.event||null,unread:true};st.news.push(n);if(st.news.length>120)st.news=st.news.slice(-120);return n}
function addNews(category,headline,deck,body,opts={}){return pushNews(s,category,headline,deck,body,opts)}
function seedOpeningNews(st){let mn=st.managedNation,p=NATIONS[mn];pushNews(st,'Federation',`${p.name} appoint new Performance Director`,`A new four-year cycle begins for ${p.name}.`,`The national programme has confirmed a new Performance Director with responsibility for senior selection, development, staffing and Olympic performance across the coming four-year cycle.`,{priority:'major',nation:mn});let stars=[...st.athletes].filter(a=>a.nation!==mn).sort((a,b)=>performanceScore(b)-performanceScore(a)).slice(0,3);pushNews(st,'World',`New season: ${stars[0].name} heads global watchlist`,`${stars.map(a=>`${flag(a.nation)} ${a.name}`).join(', ')} enter the year among athletics' leading names.`,`The international season opens with established stars under pressure from a deeper global field. Ranking points, world leads and championship selection will shape the road to the Games.`,{priority:'major'});pushNews(st,'Preview',`${p.name} begin Year 1 with ${st.athletes.filter(a=>a.nation===mn&&a.inSquad!==false).length}-athlete squad`,`Expectations are ${p.expectation.toLowerCase()} as the programme starts its Olympic cycle.`,`Attention turns first to pre-season preparation before the opening competitive block. The performance team will be judged on development, ranking movement and major championship results.`,{nation:mn})}
function latestNews(n=5){return [...s.news].sort((a,b)=>(b.season-a.season)||(b.week-a.week)).slice(0,n)}
function newsUnread(){return s.news.filter(n=>n.unread).length}
function seasonLead(d){return s.seasonLeads?.[d]||null}
function registerPerformance(a,d,perf,source,eventName){a.profileResults??=(s.performances||[]).filter(p=>p.athleteId===a.id&&p.disc===a.disc).map(p=>({season:p.season,week:p.week,perf:p.perf,event:p.event,source:p.source,achievements:p.achievements||[]}));let rec={id:'pf'+Date.now()+Math.random().toString(16).slice(2),season:s.game.season,week:s.game.week,athleteId:a.id,name:a.name,nation:a.nation,disc:d,perf,source,event:eventName};if(a.selectionSeason?.season!==s.game.season){const prior=selectionHistory(a);a.selectionSeason={season:s.game.season,best:prior.length?prior.map(p=>p.perf).reduce((x,y)=>better(d,y,x)?y:x):perf}}if(better(d,perf,a.selectionSeason.best))a.selectionSeason.best=perf;s.performances.push(rec);if(s.performances.length>1000)s.performances=s.performances.slice(-1000);let ach=[];let lead=s.seasonLeads[d];if(!lead||better(d,perf,lead.value)){s.seasonLeads[d]={value:perf,athleteId:a.id,name:a.name,nation:a.nation,event:eventName,week:s.game.week};ach.push('WL')}let wr=s.records.world[d];if(wr&&better(d,perf,wr.value)){s.records.world[d]={value:perf,holder:a.name,nation:a.nation,season:s.game.season};ach.push('WR')}let nr=s.records.national[a.nation]?.[d];if(nr&&better(d,perf,nr.value)){s.records.national[a.nation][d]={value:perf,holder:a.name,nation:a.nation,season:s.game.season};ach.push('NR')}if(better(d,perf,a.pb)){a.pb=perf;ach.push('PB')}rec.achievements=ach;a.profileResults.push({season:rec.season,week:rec.week,perf:rec.perf,event:rec.event,source:rec.source,achievements:ach});return ach}
function performanceScore(a){if(window.AMAthletePerformance?.selectionScore)return window.AMAthletePerformance.selectionScore(a);const d=a?.disc,q=DISCIPLINES?.[d],pb=Number(a?.pb),wr=Number(WORLD_RECORDS?.[d]),ratio=pb>0&&wr>0?(q?.type==='time'?wr/pb:pb/wr):.75,evidence=clamp(((ratio-.62)/.38)*100,0,100),ready=clamp((Number(a?.form)||80)*.40+(Number(a?.fitness)||85)*.35+(100-(Number(a?.fatigue)||15))*.25,0,100);return evidence*.78+ready*.22}
function buildEventField(e,d){if(e.id==='olympics')return olympicField(e,d);let mn=managedNation(),ownIds=new Set(e.entries[d]||[]),own=s.athletes.filter(a=>!a.retired&&a.disc===d&&a.nation===mn&&a.injury===0&&!activityBusy(a,e.week)&&a.inSquad!==false&&ownIds.has(a.id));if(e.level==='National'){let domestic=s.athletes.filter(a=>!a.retired&&a.disc===d&&a.nation===mn&&a.injury===0&&!activityBusy(a,e.week)&&a.inSquad===false&&!ownIds.has(a.id)).sort((a,b)=>performanceScore(b)-performanceScore(a)).slice(0,Math.max(6-own.length,3));return [...own,...domestic]}let limit=e.kind==='olympics'||e.level==='World'?12:9;let world=s.athletes.filter(a=>!a.retired&&a.disc===d&&a.nation!==mn&&a.injury===0&&!activityBusy(a,e.week)).sort((a,b)=>performanceScore(b)-performanceScore(a));let picked=[],nationCount={};for(let a of world){if((nationCount[a.nation]||0)>=2)continue;picked.push(a);nationCount[a.nation]=(nationCount[a.nation]||0)+1;if(picked.length>=Math.max(6,limit-own.length))break}return [...own,...picked]}
function rawPerformance(a,d,staffBonus=0){if(window.AMAthletePerformance?.simulate)return window.AMAthletePerformance.simulate(a,d,staffBonus);const q=DISCIPLINES[d],pb=Math.max(.01,Number(a?.pb)||1),cond=(Number(a?.form)||80)*.42+(Number(a?.fitness)||85)*.30+(100-(Number(a?.fatigue)||15))*.28,ready=(cond-80)/100;if(q.type==='time'){const gap=clamp(.014-ready*.012-(Number(staffBonus)||0)*.0005,.003,.024);return +(pb*(1+gap+rand(-.0035,.0045))).toFixed(2)}if(q.type==='height'){return +clamp(pb-.055+ready*.05+(Number(staffBonus)||0)*.004+rand(-.035,.035),pb-.14,pb+.04).toFixed(2)}return +clamp(pb*.95+ready*pb*.025+(Number(staffBonus)||0)*.025+rand(-pb*.018,pb*.014),pb*.88,pb*1.01).toFixed(2)}
function rivalryActive(pair){return !!(pair.formed&&(s.game.careerWeek||s.game.week)-pair.lastClose<=52&&pair.ids.every(id=>s.athletes.some(a=>a.id===id&&!a.retired)))}
function recordRivalries(eventKey,d,results,eventName){if(!DISCIPLINES[d])return;const rows=[...new Map(results.filter(x=>Number.isFinite(x.perf)&&x.perf>0&&s.athletes.some(a=>a.id===x.id&&!a.retired)).map(x=>[x.id,x])).values()];if(rows.length<2)return;const state=s.rivalries??={pairs:{},processed:{}};if(state.processed[eventKey])return;state.processed[eventKey]=true;const week=s.game.careerWeek||s.game.week,limit=isSprintDiscipline(d)?sprintCloseMargin(d):d.includes('HJ')?.05:.35,formed=[];for(let i=0;i<rows.length;i++)for(let j=i+1;j<rows.length;j++){const x=rows[i],y=rows[j],ids=[x.id,y.id].sort((a,b)=>String(a).localeCompare(String(b))),key=JSON.stringify([d,...ids]),gap=Math.abs(x.perf-y.perf),close=gap<=limit+.000001;let pair=state.pairs[key];if(!pair&&!close)continue;if(!pair)pair=state.pairs[key]={ids,disc:d,meetings:0,wins:{},ties:0,closeWeeks:[],formed:false,lastClose:week,history:[]};pair.meetings++;if(gap<.00001)pair.ties++;else{const winner=better(d,x.perf,y.perf)?x.id:y.id;pair.wins[winner]=(pair.wins[winner]||0)+1}if(close){pair.lastClose=week;pair.closeWeeks.push(week)}pair.closeWeeks=pair.closeWeeks.filter(w=>week-w<=52);pair.lastMeeting=week;pair.history.push({season:s.game.season,week:s.game.week,event:eventName,marks:{[x.id]:x.perf,[y.id]:y.perf},close});pair.history=pair.history.slice(-6);if(!pair.formed&&pair.closeWeeks.length>=3){pair.formed=true;formed.push(pair);for(const id of ids){const a=s.athletes.find(a=>a.id===id),other=s.athletes.find(a=>a.id===ids.find(z=>z!==id));rememberAthlete(a,'Rivalry',`Three close contests have established a rivalry with ${other.name}.`)}}}formed.sort((a,b)=>Number(b.ids.some(id=>s.athletes.find(x=>x.id===id)?.nation===managedNation()))-Number(a.ids.some(id=>s.athletes.find(x=>x.id===id)?.nation===managedNation())));const pair=formed[0];if(pair){const [a,b]=pair.ids.map(id=>s.athletes.find(x=>x.id===id));addNews('Rivalries',`${a.name} and ${b.name}: a rivalry takes shape`,`${discLabel(d)} • Three close contests within a year`,`${a.name} and ${b.name} have repeatedly finished close together. They were close again at ${eventName}. Tracked head-to-head: ${pair.wins[a.id]||0} to ${pair.wins[b.id]||0}, with ${pair.ties} equal mark(s). The head-to-head is now being tracked.`,{nation:a.nation,athleteId:a.id,event:eventName})}}
function rivalryCommentary(d,field){const ids=new Set(field.map(x=>x.id)),pairs=Object.values(s.rivalries?.pairs||{}).filter(p=>p.disc===d&&rivalryActive(p)&&p.ids.every(id=>ids.has(id)&&s.athletes.find(a=>a.id===id)?.injury===0)).sort((a,b)=>b.lastClose-a.lastClose||b.meetings-a.meetings),pair=pairs[0];if(!pair)return '';const [a,b]=pair.ids.map(id=>s.athletes.find(x=>x.id===id));return `FAMILIAR RIVALS
${a.name} and ${b.name} meet again. Their tracked head-to-head before today is ${pair.wins[a.id]||0} to ${pair.wins[b.id]||0}, with ${pair.ties} equal mark(s). Three close meetings have made this a genuine head-to-head.`}
function rivalryProfileHTML(a){const pairs=Object.values(s.rivalries?.pairs||{}).filter(p=>p.formed&&p.ids.includes(a.id)).sort((x,y)=>Number(rivalryActive(y))-Number(rivalryActive(x))||y.lastClose-x.lastClose).slice(0,4);if(!pairs.length)return '';return `<section class="profile-panel"><h2>Rivalries</h2><p>Records start from the first close contest tracked in this save. Equal marks count as ties, regardless of the official result order.</p>${pairs.map(pair=>{const other=s.athletes.find(x=>pair.ids.includes(x.id)&&x.id!==a.id);if(!other)return '';return `<div class="profile-fixture"><span><strong>${athleteLink(other)}</strong><small>${rivalryActive(pair)?'Active rivalry':other.retired||a.retired?'Archived rivalry':'Dormant rivalry'} • ${discLabel(pair.disc)}</small><p>${pair.wins[a.id]||0} wins • ${pair.wins[other.id]||0} losses • ${pair.ties} ties across ${pair.meetings} tracked meetings</p><details><summary>Recent meetings</summary>${pair.history.slice().reverse().map(m=>`<p>${m.season}, Week ${m.week} • ${profileEscape(m.event)}<br>${profileEscape(a.name)} ${fmtPerf(pair.disc,m.marks[a.id])} / ${profileEscape(other.name)} ${fmtPerf(pair.disc,m.marks[other.id])}${m.close?' • Close contest':''}</p>`).join('')}</details></span></div>`}).join('')}</section>`}
function commitDisciplineResults(e,d,r){if(Array.isArray(e.results?.[d]))return;immersionState();recordSelectionDecisions(e,d);let mn=managedNation(),q=DISCIPLINES[d];r.forEach((x,i)=>{x.points=e.ranked?Math.round((PTS[i]||0)*rankingPointMultiplier(e)):0;let a=s.athletes.find(y=>y.id===x.id);if(!a)return;a.points+=x.points;s.nationPoints[x.nation]=(s.nationPoints[x.nation]||0)+x.points;recordAthleteAppearance(e,d,a,x,i);if(['competition','championship','olympics'].includes(e.kind))recordTraitResult(a,d,x.perf,`${s.game.season}:${e.id}:${e.week}:${d}`);x.achievements=registerPerformance(a,d,x.perf,'event',e.name);if(a.nation===mn){a.form=clamp(a.form+(i<3?2:0)-1,55,99);a.fatigue=clamp(a.fatigue+rint(6,12),0,100);if(e.kind==='olympics'&&i<3){let key=i===0?'g':i===1?'s':'b';a.medals[key]++;s.medals[key]++;s.game.careerScore+=i===0?100:i===1?60:40}}});e.results[d]=r;recordManagementResults(e,d,r);if(['competition','championship','olympics'].includes(e.kind))recordRivalries(`${s.game.season}:${e.id}:${e.week}:${d}`,d,r,e.name)}
function generateEventNews(e){let winners=[];Object.keys(e.results||{}).forEach(d=>{let r=e.results[d]||[];if(!r.length)return;let w=r[0];winners.push(`${flag(w.nation)} ${w.name} (${fmtPerf(d,w.perf)})`);r.forEach(x=>{let ach=x.achievements||[];if(ach.includes('WR'))addNews('Records',`WORLD RECORD: ${x.name} rewrites ${discLabel(d)} history`,`${flag(x.nation)} ${x.name} produces ${fmtPerf(d,x.perf)} at ${e.name}.`,`The world record has been broken. ${x.name} delivered ${fmtPerf(d,x.perf)} in ${discLabel(d)}, setting a new world record during ${e.name}.`,{priority:'breaking',nation:x.nation,athleteId:x.id,event:e.name});else if(ach.includes('NR')&&x.nation===managedNation())addNews('Records',`${x.name} sets new ${nationName(x.nation)} record`,`${fmtPerf(d,x.perf)} becomes the new national benchmark in ${discLabel(d)}.`,`${x.name} has broken the national record with ${fmtPerf(d,x.perf)} at ${e.name}.`,{priority:'major',nation:x.nation,athleteId:x.id,event:e.name})})});if(winners.length){let headline=e.kind==='olympics'?`${e.name}: medals decided across athletics programme`:`${e.name}: ${winners[0].replace(/\([^)]*\)/,'').trim()} leads the headlines`;addNews('Results',headline,winners.slice(0,3).join(' • '),`${winners.join(' • ')}. World ranking points and season leads have been updated.`,{priority:e.star>=5?'major':'normal',event:e.name})}}
function simulateWorldWeek(){let world=s.athletes.filter(a=>!a.retired&&a.nation!==managedNation());world.forEach(a=>{if(a.injury>0){if(!seriousInjuryActive(a))a.injury--;return}a.form=clamp(a.form+rint(-2,2),70,98);a.fatigue=clamp(a.fatigue+rint(-5,5),0,55)});if(Math.random()<.18){let stars=world.filter(a=>performanceScore(a)>=78&&a.injury===0);if(stars.length){let a=stars[rint(0,stars.length-1)];a.injury=rint(1,4);addNews('Injuries',`${a.name} hit by ${a.injury}-week injury setback`,`${flag(a.nation)} ${nationName(a.nation)} face a selection concern in ${discLabel(a.disc)}.`,`International reports indicate ${a.name} will miss approximately ${a.injury} week${a.injury===1?'':'s'}. The setback could affect ranking opportunities and championship preparation.`,{priority:performanceScore(a)>=88?'major':'normal',nation:a.nation,athleteId:a.id})}}if(Math.random()>.58)return;let disciplines=Object.keys(DISCIPLINES),d=disciplines[rint(0,disciplines.length-1)],city=WORLD_TOUR_CITIES[rint(0,WORLD_TOUR_CITIES.length-1)],field=world.filter(a=>a.disc===d&&a.injury===0&&!activityBusy(a)).sort((a,b)=>performanceScore(b)-performanceScore(a)).slice(0,8);if(field.length<4)return;let r=field.map(a=>({id:a.id,name:a.name,nation:a.nation,flag:flag(a.nation),perf:rawPerformance(a,d)}));r.sort((a,b)=>DISCIPLINES[d].type==='time'?a.perf-b.perf:b.perf-a.perf);r.forEach((x,i)=>{let a=s.athletes.find(z=>z.id===x.id),pts=WORLD_TOUR_POINTS[i]||0;a.points+=pts;s.nationPoints[a.nation]=(s.nationPoints[a.nation]||0)+pts;recordTraitResult(a,d,x.perf,`${s.game.season}:tour:${s.game.careerWeek||s.game.week}:${city}:${d}`);x.achievements=registerPerformance(a,d,x.perf,'world-tour',city+' World Tour');x.points=pts});recordRivalries(`${s.game.season}:tour:${s.game.careerWeek||s.game.week}:${city}:${d}`,d,r,city+' World Tour');let w=r[0];let ach=w.achievements||[];let headline=ach.includes('WR')?`WORLD RECORD: ${w.name} storms to ${fmtPerf(d,w.perf)} in ${city}`:ach.includes('WL')?`${w.name} takes world lead in ${city}`:`${w.name} wins ${city} World Tour ${discLabel(d)}`;addNews(ach.includes('WR')?'Records':'World Tour',headline,`${flag(w.nation)} ${w.name} wins in ${fmtPerf(d,w.perf)}.`,`The global circuit moved to ${city} this week, where ${w.name} took victory in ${discLabel(d)}. ${r.slice(0,3).map((x,i)=>`${i+1}. ${x.name} ${fmtPerf(d,x.perf)}`).join(' • ')}`,{priority:ach.includes('WR')?'breaking':ach.includes('WL')?'major':'normal',nation:w.nation,athleteId:w.id,event:city+' World Tour'})}
function newMail(senderName,subject,body,type='info',eventId=null){let id=pushMail(s,senderName,subject,body,type,eventId);save();syncMailBadge();return id}
