function mailAbsoluteWeek(m){return ((Number(m?.year)||1)-1)*52+(Number(m?.week)||1)}
function pruneOldEmails(){if(!s?.emails||!s?.game)return 0;const now=((Number(s.game.cycleYear)||1)-1)*52+(Number(s.game.week)||1),before=s.emails.length,kept=s.emails.filter(m=>now-mailAbsoluteWeek(m)<=4);if(kept.length===before)return 0;const ids=new Set(kept.map(m=>m.id));s.emails=kept;if(openMail&&!ids.has(openMail))openMail=kept[kept.length-1]?.id||null;syncMailBadge();return before-kept.length}
