function renderMenu(){applyNationTheme();let raw=localStorage.getItem(SAVE_KEY),has=!!raw;let g=has?s.game:null,p=has?nationProfile():null;$('latestUpdatePanel').innerHTML=`<div class="update-panel-title"><strong>Development Updates</strong><span>${UPDATES.length} releases</span></div>${UPDATES.map((u,i)=>`<section class="update-entry ${i===0?'latest':''}"><div class="latest-update-head"><strong>${i===0?'Latest Update':'Previous Update'}</strong><span>${u.date}</span></div><h3>${u.title}</h3><ul>${u.items.map(x=>`<li>${x}</li>`).join('')}</ul></section>`).join('')}`;$('continueBtn').disabled=!has;$('careerTitle').textContent=has?`${p.flag} ${p.name}`:'Choose a Nation';$('railNation').textContent=has?`${p.name}`:'National Programme';$('saveCard').innerHTML=has?`<div class="save-grid"><div class="save-stat"><small>Nation</small><strong style="font-size:14px">${p.flag} ${p.name}</strong></div><div class="save-stat"><small>Career</small><strong>Year ${careerState().careerYear}/40</strong></div><div class="save-stat"><small>Olympic Cycle</small><strong>${careerState().cycleNumber}/10 • Y${g.cycleYear}/4</strong></div><div class="save-stat"><small>Week / Funding</small><strong>W${g.week} • ${money(s.funding)}</strong></div></div>`:`<div class="muted" style="font-size:11px;line-height:1.6">No career save yet. Choose a nation and begin a 40-year career across up to ten Olympic cycles.</div>`}
