 const name=buildProspectName(nation,female),overall=clamp(rint(58,70)+Math.min(5,level)+identityMod.ability,55,78),potential=clamp(overall+rint(10,23)+identityMod.potential,overall,95),q=DISCIPLINES[disc],pb=q.type==='time'?(female?11.1:10.1)+(90-overall)*.035:q.type==='height'?(female?1.95:2.25)-(90-overall)*.011:(female?19.5:21.5)-(90-overall)*.14,projectionSpread=Math.max(1,6-level),devProjectionBase=clamp(potential+rint(-projectionSpread,projectionSpread),overall,99);
