function generateProspects(count=1,reason='Scouting event'){const scout=scoutingState(),found=[];for(let i=0;i<count;i++)found.push(newProspect(managedNation(),scout.focus,s.staff.scout));for(const a of found)scout.reports.push({athleteId:a.id,season:s.game.season,week:s.game.week,reason});if(found.length){if(s.coaches?.scout)recordCoachMove(s.coaches.scout,'Identified new prospects: '+found.map(a=>a.name).join(', ')+'.');newMail(sender('pathway'),'Scouting report: '+found.length+' new prospect'+(found.length===1?'':'s'),found.map(a=>`${a.name}, age ${a.age}, ${discLabel(a.disc)}. Personal best ${fmtPerf(a.disc,a.pb)}. Staff ability range ${assessmentText(a,'overall')}; development grade ${developmentGradeText(a)} (${assessmentConfidenceLabel(a,'potential')[0].toLowerCase()}). Added to your national pool.`).join(' '),'scouting');addNews('Scouting',`${nationName(managedNation())} identify ${found.length} new prospect${found.length===1?'':'s'}`,found.map(a=>a.name).join(', '),'The scouting network has added newly discovered athletes to the national pool. They can compete in domestic meetings and be considered for a squad call-up.',{nation:managedNation()})}return found}
