function injuryGroup(a){return isSprintDiscipline(a.disc)?'sprint':String(a.disc).includes('HJ')?'jump':'throw'}
function injuryHtmlSections(sections){return sections.map(([title,text])=>`<div class="mail-section"><h3>${profileEscape(title)}</h3><p>${profileEscape(text)}</p></div>`).join('')}
function sendMedicalReport(a,subject,summary,sections){if(a.nation!==managedNation())return null;const html=`<p>${profileEscape(summary)}</p>${injuryHtmlSections(sections)}`,id=pushMail(s,sender('medical'),subject,summary,'medical',null,html);save();syncMailBadge();return id}
function seriousInjuryActive(a){return !!(a.seriousInjury&&!['recovered','retired'].includes(a.seriousInjury.stage))}
