 archiveInjuryCase(a);const start=s.game.careerWeek||s.game.week;a.injuryCase={diagnosis:def.diagnosis,cause,startCareerWeek:start,initialExpectedWeeks:expected,expectedWeeks:expected,stage:'diagnosis',active:true,earlyReviewed:false,earlyBy:0,updates:[{stage:'diagnosis',season:s.game.season,week:s.game.week,body:`${a.name} was diagnosed with ${def.diagnosis} after they ${cause}. The initial estimate is ${expected} week${expected===1?'':'s'} out.`}]};a.injury=expected;a.fitness=Math.min(a.fitness,82);
