 sendMedicalReport(a,`Medical report: ${a.name} — ${def.diagnosis}`,summary,[['Diagnosis',def.diagnosis],['How it happened',`${a.name} ${cause}.`],['Expected absence',`Approximately ${expected} week${expected===1?'':'s'}. This is an initial estimate rather than a fixed return date.`],['Medical plan',`The athlete will move into rehabilitation and reduced loading. The medical team will review progress during recovery; a good response can lead to earlier clearance.`]]);
