 if(a.injury===0){c.active=false;c.stage='recovered';c.recoveredCareerWeek=cw;c.updates.push({stage:'recovered',season:s.game.season,week:s.game.week,body:`${a.name} received medical clearance${c.earlyBy?` ${c.earlyBy} week${c.earlyBy===1?'':'s'} earlier than first expected`:''}.`});athleteStory(a).awaitingComeback=true;rememberAthlete(a,'Recovery',`Cleared after ${c.diagnosis}${c.earlyBy?`; returned ${c.earlyBy} week${c.earlyBy===1?'':'s'} ahead of the original estimate`:''}.`);sendMedicalReport(a,`Medical clearance: ${a.name}`,`${a.name} has completed rehabilitation for ${c.diagnosis} and is available for selection again.`,[['Recovery outcome',c.earlyBy?`The athlete was cleared ${c.earlyBy} week${c.earlyBy===1?'':'s'} earlier than the original estimate.`:'Recovery finished in line with the current medical estimate.'],['Current status','Available for competition and normal selection.'],['Return plan','Fitness and form may still need rebuilding. Consider a controlled return rather than immediately stacking high-load competitions.']])}
