function startSeriousInjury(a){if(!a||a.retired||a.injury>0||seriousInjuryActive(a))return false;const defs=SERIOUS_INJURIES[injuryGroup(a)],def=defs[rint(0,defs.length-1)],cause=def.causes[rint(0,def.causes.length-1)],start=s.game.careerWeek||s.game.week,expected=rint(def.min,def.max);a.seriousInjury={diagnosis:def.diagnosis,cause,startCareerWeek:start,expectedWeeks:expected,initialExpectedWeeks:expected,returnCareerWeek:start+expected,stage:'new',updates:[],earlyBy:0};a.injury=expected;a.fitness=Math.min(a.fitness,55);for(const e of s.events.filter(e=>!e.completed)){for(const d of Object.keys(e.entries||{})){if(e.entries[d].includes(a.id)){e.entries[d]=e.entries[d].filter(id=>id!==a.id);e.decision=false}}}injuryStoryUpdate(a,'diagnosis','serious injury confirmed',`${a.name} has suffered ${def.diagnosis} after they ${cause}. The initial estimate is around ${expected} weeks away from competition. Rehabilitation begins immediately, future entries have been withdrawn, and the medical team will review whether the return date can move forward or needs extending.`);return true}
