function importManagerResults(){const m=managementState(),base=s.game.season-(s.game.cycleYear||1);for(const e of [...(s.history||[]).map(h=>({...h,name:h.event,season:base+(h.year||1)})),...(s.events||[]).map(e=>({...e,season:s.game.season}))]){if(e.kind==='testing'||/testing/i.test(e.name||''))continue;for(const [d,rows] of Object.entries(e.results||{})){if(!Array.isArray(rows))continue;const key=managementResultKey(e.season,e.name,e.week,d);if(m.results[key])continue;const own=rows.map((r,i)=>({...r,place:i+1})).filter(r=>r.nation===managedNation());if(own.length)m.results[key]={season:e.season,week:e.week,event:e.name,disc:d,national:e.level==='National'||/national championships/i.test(e.name||''),olympic:e.kind==='olympics'||/olympic/i.test(e.name||''),rows:own}}}return Object.values(m.results)}
