function financeState(){s.finance??={ledger:[]};s.finance.ledger??=[];return s.finance}
function recordFinance(amount,label,category='Programme'){const f=financeState();f.ledger.push({season:s.game.season,week:s.game.week,amount:Number(amount)||0,label:String(label||category),category});f.ledger=f.ledger.slice(-60)}
function annualStaffExposure(){ensureCoaches();return Object.values(s.coaches||{}).filter(Boolean).reduce((sum,c)=>sum+(c.level||1)*120000,0)}
function staffContractsDue(within=12){ensureCoaches();return Object.entries(s.coaches||{}).map(([role,c])=>c?{role,c,left:Math.max(0,c.until-coachWeek())}:null).filter(Boolean).filter(x=>x.left<=within).sort((a,b)=>a.left-b.left)}
