function staffOverviewHTML(){ensureCoaches();const rows=Object.entries(STAFF_DEF).map(([role,d])=>({role,d,c:s.coaches[role],level:s.staff[role]||1})),covered=rows.filter(x=>x.c).length,avg=(rows.reduce((n,x)=>n+x.level,0)/rows.length).toFixed(1),due=staffContractsDue(12),strong=[...rows].sort((a,b)=>b.level-a.level)[0],identity=nationalIdentityState(managedNation());return `<div class="staff-overview"><section class="staff-hero"><small>PERFORMANCE TEAM</small><h2>${covered}/${rows.length} specialist roles covered</h2><p>Your staff shape training quality, recovery, scouting confidence and competition preparation. Contracts are paid upfront, so the key decision here is whether each specialist is worth keeping for the next block.</p><div class="finance-health ${due.length>=3?'pressure':due.length?'tight':''}"><i></i>${due.length?`${due.length} contract${due.length===1?'':'s'} need attention within 12 weeks`:'No immediate contract pressure'}</div></section><div class="staff-summary-grid"><div class="staff-summary"><small>Team Ability</small><strong>${avg}/5</strong><span>Average across six departments</span></div><div class="staff-summary"><small>Strongest Area</small><strong>${strong?STAFF_DEF[strong.role].name:'—'}</strong><span>${strong?`Ability ${strong.level}/5`:'No appointment'}</span></div><div class="staff-summary"><small>Contracts Due</small><strong>${due.length}</strong><span>Inside the next 12 weeks</span></div><div class="staff-summary"><small>Programme Direction</small><strong>${profileEscape(nationalIdentityLabel(managedNation()))}</strong><span>Sprint ${identity.sprint} · Field ${identity.field} · Pathway ${identity.pathway}</span></div></div></div>`}
function coachesHTML(){ensureCoaches();return `<section class="panel"><div class="panel-h"><strong>Performance Team</strong><span>Current appointments & recruitment</span></div><div class="panel-body"><div class="staff-roster">${Object.entries(STAFF_DEF).map(([role,d])=>{const c=s.coaches[role],left=c?Math.max(0,c.until-coachWeek()):0,level=s.staff[role]||1,contractClass=left<=4?'urgent':left<=12?'due':'';return `<article class="staff-person-card"><div class="staff-person-head"><div><small>${profileEscape(d.name.toUpperCase())}</small><h3>${c?`<button class="athlete-link" data-coach="${c.id}">${profileEscape(c.name)}</button>`:'Interim cover'}</h3></div><span class="staff-contract ${contractClass}">${c?`${left}W LEFT`:'INTERIM'}</span></div><div class="staff-ability-row"><div>${staffPips(level)}</div><strong>Ability ${level}/5</strong></div><div class="staff-person-meta">${profileEscape(d.desc)}${c?`<br>Renewal: ${money(c.level*120000)}${c.inherited?' · inherited first term covered':''}`:'<br>Level 1 cover remains until a specialist is appointed.'}</div><div class="staff-card-actions">${c?`<button class="btn ghost" data-coach="${c.id}">VIEW PROFILE</button><button class="btn secondary" data-renew="${role}" ${left>4||s.funding<c.level*120000?'disabled':''}>${left>4?'RENEWAL LOCKED':'RENEW · '+money(c.level*120000)}</button>`:''}</div><details class="staff-shortlist"><summary>Recruitment shortlist</summary>${coachCandidates(role).map(x=>`<div class="staff-recruit"><div><strong><button class="athlete-link" data-coach="${x.id}">${profileEscape(x.name)}</button></strong><p>Ability ${x.level}/5 · 52 weeks · ${money(x.pay)} contract + ${money(x.fee)} appointment fee</p></div><button class="btn secondary" data-hire="${x.id}" data-role="${role}" ${c?.id===x.id||s.funding<x.pay+x.fee?'disabled':''}>${c?.id===x.id?'CURRENT':'APPOINT · '+money(x.pay+x.fee)}</button></div>`).join('')}</details></article>`}).join('')}</div>${s.coachHistory?.length?`<details style="margin-top:12px"><summary>Staff appointment history</summary>${s.coachHistory.slice(-12).reverse().map(x=>`<p>Career week ${x.week}: ${profileEscape(x.text)}</p>`).join('')}</details>`:''}</div></section>`}
function financeOverviewHTML(){ensureCoaches();const blueprint=nationalIdentityBlueprint(managedNation()),grant=blueprint.annualGrant,staffExposure=annualStaffExposure(),due4=staffContractsDue(4).reduce((sum,x)=>sum+x.c.level*120000,0),facSpend=seasonFacilitySpend(),deal=managementState().sponsors[s.game.season],after=s.funding-due4,health=after<500000?'pressure':after<1500000?'tight':'',healthText=health==='pressure'?'Budget under pressure':health==='tight'?'Limited headroom':'Healthy headroom';return `<div class="finance-overview"><section class="finance-hero"><small>FEDERATION FINANCE</small><h2>${money(s.funding)} available</h2><p>This is the money you can commit now. Core federation funding is refreshed at the season review; sponsorship, prize money and performance bonuses can add to it during the year.</p><div class="finance-health ${health}"><i></i>${healthText}${due4?` · ${money(due4)} of staff renewals are currently actionable`:''}</div></section><div class="finance-summary-grid"><div class="finance-summary"><small>Annual Core Grant</small><strong>${money(grant)}</strong><span>${nationName(managedNation())} federation baseline</span></div><div class="finance-summary"><small>Annual Staff Exposure</small><strong>${money(staffExposure)}</strong><span>If every current specialist is renewed for 52 weeks</span></div><div class="finance-summary"><small>Facility Spend</small><strong>${money(facSpend)}</strong><span>Invested this season</span></div><div class="finance-summary"><small>Sponsorship</small><strong>${deal?money(deal.upfront):'Not signed'}</strong><span>${deal?profileEscape(deal.name):'One deal available each season'}</span></div></div></div>`}
function financeCommitmentsHTML(){ensureCoaches();const due=Object.entries(s.coaches||{}).filter(([,c])=>c).map(([role,c])=>({role,c,left:Math.max(0,c.until-coachWeek())})).sort((a,b)=>a.left-b.left),deal=managementState().sponsors[s.game.season];return `<section class="panel"><div class="panel-h"><strong>Known Commitments</strong><span>What your current balance may need to cover</span></div><div class="panel-body"><div class="finance-commitments">${due.slice(0,6).map(x=>`<div class="finance-line"><div><strong>${STAFF_DEF[x.role].name} · ${profileEscape(x.c.name)}</strong><small>${x.left} weeks remaining on current contract</small></div><b>${money(x.c.level*120000)} renewal</b></div>`).join('')}<div class="finance-line"><div><strong>Next facility step</strong><small>Cheapest currently available upgrade across your three national centres</small></div><b>${(()=>{const costs=Object.keys(FACILITY_DEF).filter(k=>facilityLevel(k)<5).map(k=>facilityCost(k));return costs.length?money(Math.min(...costs)):'All maxed'})()}</b></div>${deal?`<div class="finance-line"><div><strong>${profileEscape(deal.name)}</strong><small>Current sponsor · ${profileEscape(deal.goal)}</small></div><b>${deal.bonus?money(deal.bonus)+' possible':'Guaranteed'}</b></div>`:''}</div></div></section>`}
function financeLedgerHTML(){const rows=[...financeState().ledger].reverse().slice(0,12);return `<section class="panel"><div class="panel-h"><strong>Recent Financial Activity</strong><span>Tracked from this finance update onward</span></div><div class="panel-body">${rows.length?`<div class="finance-ledger">${rows.map(x=>`<div class="finance-ledger-row"><small>${x.season} · W${x.week}</small><strong>${profileEscape(x.label)}</strong><b class="${x.amount>=0?'pos':'neg'}">${x.amount>=0?'+':'−'}${money(Math.abs(x.amount))}</b></div>`).join('')}</div>`:'<p class="muted">No tracked transactions yet. New sponsorship income, staff appointments, renewals, facility investment and major programme spending will appear here.</p>'}</div></section>`}
const FACILITY_DEF={sprint:{name:'Sprint Centre',desc:'Supports 100m squad athletes. Each level adds 0.15 to weekly training form gain before load and morale modifiers, and a small competition preparation bonus.'},field:{name:'Jumps & Throws Centre',desc:'Supports high jump and shot put squad athletes. Each level adds 0.15 to weekly training form gain before load and morale modifiers, and a small competition preparation bonus.'},recovery:{name:'Recovery Suite',desc:'Supports the whole squad. Each extra level removes 1 more fatigue per week. Each level adds 0.25 fitness during normal training; extra levels add 0.5 fitness during recovery or injury rehabilitation. Does not shorten injury duration.'}};
function facilityLevel(key){const raw=s.facilityLevels?.[key]??s.facilities??1;return Math.max(1,Math.min(5,Math.floor(Number(raw)||1)))}
function athleteFacility(a){return facilityLevel(isSprintDiscipline(a.disc)?'sprint':'field')}
function facilityCost(key){return 600000+facilityLevel(key)*300000}
function facilityArtHTML(key,level){const rows={sprint:0,field:1,recovery:2};if(!Object.hasOwn(rows,key))return '';const n=Math.max(1,Math.min(5,Math.floor(Number(level)||1))),stages=['Foundation','Established','Advanced','High Performance','Elite'];return `<div class="facility-art" role="img" aria-label="${FACILITY_DEF[key].name}, Level ${n}: ${stages[n-1]}" style="background-position:${(n-1)*25}% ${rows[key]*50}%"></div><div class="facility-stage">${stages[n-1]} · Level ${n}</div>`}
function facilitiesHTML(){return `<section class="panel"><div class="panel-h"><strong>National Facilities</strong><span>Permanent programme investments</span></div><div class="panel-body"><p class="muted">Choose where to invest. Upgrades apply immediately to your national squad, including athletes called up later. Existing facility investment carries over to all three centres. Levels run from 1 to 5.</p><div class="staff-grid">${Object.entries(FACILITY_DEF).map(([key,d])=>{const level=facilityLevel(key),cost=facilityCost(key);return `<div class="staff-card"><h3>${d.name}</h3>${facilityArtHTML(key,level)}<p>${d.desc}</p><div class="staff-level">Level ${level} / 5</div><div class="event-progress"><i style="width:${level*20}%"></i></div><p>${level===5?'Fully developed.':`Next: Level ${level+1} · ${money(cost)} one-off investment.<br>Budget after upgrade: ${money(s.funding-cost)}.`}</p><button class="btn secondary" data-facility="${key}" ${level===5||s.funding<cost?'disabled':''}>${level===5?'MAXIMUM LEVEL':s.funding<cost?'INSUFFICIENT FUNDING':'UPGRADE · '+money(cost)}</button>${level<5?`<details class="facility-preview"><summary>Preview Level ${level+1}</summary>${facilityArtHTML(key,level+1)}</details>`:''}</div>`}).join('')}</div><p class="muted">Effects combine with coaching and training choices. Weekly fitness and form changes are rounded and capped. These investments have no recurring charge.</p>${s.facilityHistory?.length?`<details><summary>Investment history</summary>${s.facilityHistory.slice(-8).reverse().map(x=>`<p>${x.season} · Week ${x.week}: ${FACILITY_DEF[x.key]?.name||'Facility'} reached Level ${x.level} · ${money(x.cost)}</p>`).join('')}</details>`:''}</div></section>`}
const COACH_NAMES=['Alex Morgan','Sam Okafor','Jordan Lee','Taylor Bennett','Robin Patel','Casey Williams','Jamie Clarke','Morgan Chen','Ashley Mensah','Cameron Reid','Riley Fischer','Drew Santos','Charlie Evans','Blair Kim','Quinn Campbell','Avery Brown','Rowan Silva','Harper Davies','Ellis Grant','Frankie Meyer','Dakota Wilson','Sasha Laurent','Reese Thomas','Skyler Jones','Jules Martin','Eden Brooks','Remy Costa','Kai Anderson','Parker Lewis','Finley Hall','Keisha Powell','Marcus Bennett','Naomi Clarke','Andre Walsh','Leonie Hart','Mika Sato'];
function coachWeek(){return s.game.careerWeek||((s.game.cycleYear||1)-1)*52+s.game.week}
function ensureCoaches(){if(s.coaches)return;s.coaches={};s.coachHistory=[];Object.keys(STAFF_DEF).forEach((role,i)=>{s.coaches[role]={id:'incumbent-'+role,name:COACH_NAMES[i*5],role,level:Math.max(1,Math.min(5,s.staff[role]||1)),until:coachWeek()+52,joined:coachWeek(),inherited:true}});save()}
function coachCandidates(role){if(!Object.hasOwn(STAFF_DEF,role))return [];const i=Object.keys(STAFF_DEF).indexOf(role);return [2,3,5].map((level,j)=>({id:role+'-'+level,name:COACH_NAMES[i*5+j+1],role,level,fee:250000,pay:level*120000}))}
function appointCoach(role,id){ensureCoaches();const c=coachCandidates(role).find(x=>x.id===id);if(!c||s.coaches[role]?.id===id)return;const cost=c.fee+c.pay;if(s.funding<cost){toast('Not enough funding');return}const previous=s.coaches[role];recordCoachMove(previous,'Left '+nationName(managedNation())+' after replacement.');s.funding-=cost;recordFinance(-cost,`${c.name} appointed as ${STAFF_DEF[role].name}`,'Staff');s.coaches[role]={...c,joined:coachWeek(),until:coachWeek()+52};s.staff[role]=c.level;recordCoachMove(s.coaches[role],'Appointed '+STAFF_DEF[role].name+' for '+nationName(managedNation())+'.');s.coachHistory.push({week:coachWeek(),text:c.name+' appointed as '+STAFF_DEF[role].name+(previous?' replacing '+previous.name:'')});newMail(sender('performance'),'Staff appointment: '+c.name,`${c.name} joins as ${STAFF_DEF[role].name}, ability ${c.level}/5. ${STAFF_DEF[role].desc} The 52-week contract is paid upfront: ${money(c.pay)} pay plus ${money(c.fee)} appointment fee. Replaced contracts receive no refund.`,'info');save();drawStaff();toast('Coach appointed')}
function renewCoach(role){ensureCoaches();const c=s.coaches[role];if(!c||c.until-coachWeek()>4)return;const cost=c.level*120000;if(s.funding<cost){toast('Not enough funding');return}s.funding-=cost;recordFinance(-cost,`${c.name} contract renewed`,'Staff');c.until=Math.max(c.until,coachWeek())+52;delete c.warned;recordCoachMove(c,'Renewed with '+nationName(managedNation())+' for 52 weeks.');s.coachHistory.push({week:coachWeek(),text:c.name+' renewed for 52 weeks'});newMail(sender('performance'),'Contract renewed: '+c.name,`${c.name} has renewed for 52 weeks. ${money(cost)} paid upfront; no appointment fee.`,'info');save();drawStaff();toast('Contract renewed')}
function updateCoachContracts(){ensureCoaches();for(const [role,c] of Object.entries(s.coaches)){if(!c)continue;const left=c.until-coachWeek();if(left<=0){recordCoachMove(c,'Left '+nationName(managedNation())+' at contract expiry.');s.coachHistory.push({week:coachWeek(),text:c.name+' left after contract expiry'});s.coaches[role]=null;s.staff[role]=1;newMail(sender('performance'),'Contract expired: '+c.name,`${c.name} has left the ${STAFF_DEF[role].name} role. The programme now uses Level 1 interim cover. Recruit a replacement in Staff.`,'info')}else if(left<=4&&!c.warned){c.warned=true;newMail(sender('performance'),'Contract decision: '+c.name,`${c.name} has ${left} weeks remaining. Renew for ${money(c.level*120000)} or recruit a replacement in Staff. If the contract expires, Level 1 interim cover takes over.`,'info')}}}
/* coaching roster redesigned in staff/finance split */
function coachArchiveHTML(){const current=new Set(Object.values(s.coaches||{}).filter(Boolean).map(c=>c.id)),past=Object.values(managementState().coachArchive).filter(c=>!current.has(c.id)&&c.history.some(h=>/Left /.test(h.text)));return past.length?`<section class="panel"><div class="panel-body"><details><summary>Former staff dossiers</summary>${past.map(c=>`<p><button class="btn ghost" data-coach="${c.id}">${profileEscape(c.name)} · ${STAFF_DEF[c.role].name}</button></p>`).join('')}</details></div></section>`:''}
function managementDialog(title,body){const el=$('managementProfile');el.innerHTML=`<div class="profile-shell"><header class="profile-top"><div><small>ATHLETICS MANAGER</small><span>Programme dossier</span></div><button class="btn ghost" data-management-close>← BACK</button></header><main class="profile-body"><h1 id="managementName">${profileEscape(title)}</h1>${body}</main></div>`;el.querySelector('[data-management-close]').onclick=()=>el.close();if(!el.open)el.showModal()}
function coachPortraitIndex(c){ensureCoachVisualIdentity(c);return Number.isInteger(c?.portraitSlot)?c.portraitSlot:0}
function coachPortraitHTML(c){const n=coachPortraitIndex(c);return `<span class="coach-portrait" role="img" aria-label="Portrait of ${profileEscape(c.name)}" style="background-position:${n%6*20}% ${Math.floor(n/6)*25}%"></span>`}
function peopleSearchKey(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}
function findPeople(query){const key=peopleSearchKey(query);if(!key)return [];const m=managementState(),people=[{type:'manager',id:'manager',name:m.name||'Performance Director',detail:'Your manager profile · '+nationName(managedNation()),aliases:'my profile manager performance director my coaching profile'}];for(const a of s.athletes||[])people.push({type:'athlete',id:a.id,name:a.name,detail:(a.retired?'Retired athlete':'Athlete')+' · '+nationName(a.nation)+' · '+discLabel(a.disc)});const coaches=new Map();for(const c of [...Object.keys(STAFF_DEF).flatMap(coachCandidates),...Object.values(m.coachArchive||{}),...Object.values(s.coaches||{})])if(c)coaches.set(c.id,c);for(const c of coaches.values())people.push({type:'coach',id:c.id,name:c.name,detail:STAFF_DEF[c.role].name+' · '+(Object.values(s.coaches||{}).some(x=>x?.id===c.id)?'Your staff':'Available / former staff')});return people.filter(p=>key.split(/\s+/).every(word=>peopleSearchKey(p.name+' '+p.detail+' '+(p.aliases||'')).includes(word))).sort((a,b)=>(peopleSearchKey(b.name)===key)-(peopleSearchKey(a.name)===key)||a.name.localeCompare(b.name))}
let peopleMatches=[];
function closePeopleSearch(){const el=$('peopleResults');el.hidden=true;$('peopleSearch').setAttribute('aria-expanded','false')}
function drawPeopleSearch(){ensureCoaches();const input=$('peopleSearch'),el=$('peopleResults');peopleMatches=findPeople(input.value);if(!input.value.trim()){closePeopleSearch();return}el.innerHTML=peopleMatches.slice(0,20).map((p,i)=>`<button data-person-index="${i}"><strong>${profileEscape(p.name)}</strong><small>${profileEscape(p.detail)}</small></button>`).join('')||'<p>No matching people. Try a name, nation, event or “manager”.</p>';if(peopleMatches.length>20)el.innerHTML+='<p>Showing the first 20 matches. Keep typing to narrow your search.</p>';el.hidden=false;input.setAttribute('aria-expanded','true');el.querySelectorAll('[data-person-index]').forEach(b=>b.onclick=()=>openPeopleMatch(Number(b.dataset.personIndex)))}
function openPeopleMatch(index){const p=peopleMatches[index];if(!p)return;closePeopleSearch();for(const id of ['athleteProfile','managementProfile'])if($(id)?.open)$(id).close();if(p.type==='athlete')openAthleteProfile(p.id);else if(p.type==='coach')openCoachProfile(p.id);else openManagerProfile()}
function openCoachProfile(id){ensureCoaches();const current=Object.values(s.coaches).find(c=>c?.id===id),candidate=Object.keys(STAFF_DEF).flatMap(coachCandidates).find(c=>c.id===id),archived=managementState().coachArchive[id],c=current||candidate||archived;if(!c)return;const d=coachDossier(c),results=Object.values(d.results),all=results.flatMap(r=>r.rows),podiums=all.filter(r=>r.place<=3).length,records=all.filter(r=>(r.achievements||[]).some(a=>['WR','NR'].includes(a))).length,athletes=[...new Set(all.map(r=>r.name))].slice(0,8);managementDialog(d.name,`<section class="profile-hero"><div class="profile-avatar">${coachPortraitHTML(d)}</div><div class="profile-identity"><h2>${STAFF_DEF[d.role].name}</h2><p>Age ${d.age+s.game.season-d.originSeason} · ${current?nationName(managedNation()):'Available for recruitment'}<br>${d.style} approach · Reputation ${Math.min(100,c.level*15+podiums+records*2)}/100</p><p>${STAFF_DEF[d.role].desc}</p></div><div class="profile-rating"><small>ABILITY</small><strong>${c.level}/5</strong></div></section><div class="profile-columns"><section class="profile-panel"><h2>Contract & coaching</h2><p>${current?`${Math.max(0,current.until-coachWeek())} weeks remaining with ${nationName(managedNation())}. Renewal: ${money(current.level*120000)}.`:`Recruitment pay: ${money(c.level*120000)} for 52 weeks, plus £250,000 appointment fee.`}</p><p>Preferred group: ${d.role==='sprint'?'100m':d.role==='jumps'?'High jump':d.role==='throws'?'Shot put':'Whole national squad'}. Ability controls the coaching effects; approach describes their working style.</p><h3>Results with your programme</h3><p>${all.length} athlete appearances supported · ${podiums} podiums · ${records} record-setting performances.</p><p>Olympic medals supported: ${results.filter(r=>r.olympic).flatMap(r=>r.rows).filter(r=>r.place<=3).length}. Reputation grows with ability, podiums and records.</p><p>${athletes.length?'Athletes coached: '+athletes.map(profileEscape).join(', '):'Results will appear after this coach works with your squad at a competition.'}</p></section><section class="profile-panel"><h2>Coaching career</h2>${d.history.slice().reverse().map(x=>`<p><strong>${x.season} · W${x.week}</strong><br>${profileEscape(x.text)}</p>`).join('')}<h3>Championship memories</h3>${results.filter(x=>/world|olympic|championship/i.test(x.event)).slice(-6).reverse().map(x=>`<p>${x.season} · ${profileEscape(x.event)}: ${x.rows.map(r=>profileEscape(r.name)+' #'+r.place).join(', ')}</p>`).join('')||'<p>No championship results recorded with your programme yet.</p>'}</section></div>`);save()}
function openManagerProfile(){ensureCoaches();const m=managementState(),results=importManagerResults(),rows=results.flatMap(x=>x.rows),wins=rows.filter(r=>r.place===1).length,podiums=rows.filter(r=>r.place<=3).length,records=rows.filter(r=>(r.achievements||[]).some(a=>['WR','NR'].includes(a))).length,titles=results.filter(x=>x.national).flatMap(x=>x.rows).filter(r=>r.place===1).length,reputation=Math.min(100,20+wins*2+records*3+(s.medals.g+s.medals.s+s.medals.b)*5);const milestones=results.flatMap(x=>x.rows.filter(r=>r.place===1||x.olympic&&r.place<=3||(r.achievements||[]).some(a=>['WR','NR'].includes(a))).map(r=>({season:x.season,week:x.week,text:`${r.name}: ${x.event}, ${discLabel(x.disc)} — place ${r.place}${r.achievements?.length?' · '+r.achievements.join(', '):''}`}))).sort((a,b)=>b.season-a.season||b.week-a.week);managementDialog(m.name,`<section class="profile-panel"><p>${nationName(managedNation())} · Performance Director</p><p>${careerLabel()}.</p><label>Your name <input id="managerNameInput" maxlength="60" value="${profileEscape(m.name)}"></label> <button class="btn secondary" id="saveManagerName">SAVE NAME</button></section><div class="profile-headline-stats">${[['Reputation',reputation+'/100'],['Event wins',wins],['Podiums',podiums],['National titles',titles],['Olympic medals',s.medals.g+s.medals.s+s.medals.b],['Records',records]].map(([k,v])=>`<div class="profile-metric"><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><section class="profile-panel"><h2>Career record</h2><p>Current programme: ${nationName(managedNation())}. Nations managed: ${careerState().nationsManaged.map(n=>flag(n)+' '+nationName(n)).join(' • ')}.</p><p>Reputation reflects recorded wins, records and Olympic medals. Contracts are reviewed after every Olympic cycle; the full management career can run for 40 seasons.</p>${careerState().completedCycles.length?`<h3>Olympic cycle record</h3>${careerState().completedCycles.slice().reverse().map(c=>`<p><strong>Cycle ${c.cycle} • ${c.startSeason}–${c.endSeason} • ${flag(c.nation)} ${profileEscape(nationName(c.nation))}</strong><br>Board score ${c.score}/100 • Olympic medals ${c.medals.g}G ${c.medals.s}S ${c.medals.b}B • Average nation rank #${c.avgRank}${c.acceptedNation&&c.acceptedNation!==c.nation?' • Moved to '+profileEscape(nationName(c.acceptedNation)):''}</p>`).join('')}`:''}${milestones.slice(0,60).map(x=>`<p><strong>${x.season} · Week ${x.week}</strong><br>${profileEscape(x.text)}</p>`).join('')||'<p>Your first competition milestone is still ahead.</p>'}</section>`);$('saveManagerName').onclick=()=>{m.name=$('managerNameInput').value.trim().slice(0,60)||'Performance Director';save();openManagerProfile()};save()}
function sponsorOffers(){const r=importManagerResults().flatMap(x=>x.rows),rep=Math.min(100,20+r.filter(x=>x.place===1).length*2+r.filter(x=>(x.achievements||[]).some(a=>['WR','NR'].includes(a))).length*3+(s.medals.g+s.medals.s+s.medals.b)*5);return [{id:'community',name:'Stride Community Sport',upfront:450000,bonus:0,goal:'Guaranteed funding; no performance target.',eligible:true},{id:'podium',name:'Apex Performance',upfront:200000,bonus:600000,goal:'Earn three international podiums after signing this season.',eligible:true},{id:'prestige',name:'Summit Elite',upfront:350000,bonus:900000,goal:'Win an international event after signing this season. Requires reputation 40 and all three facilities at Level 3 or higher to sign.',eligible:rep>=40&&['sprint','field','recovery'].every(k=>facilityLevel(k)>=3)}]}
function signSponsor(id){const m=managementState();if(m.sponsors[s.game.season]||s.game.week>=48)return;const offer=sponsorOffers().find(x=>x.id===id);if(!offer?.eligible)return;m.sponsors[s.game.season]={...offer,season:s.game.season,signedWeek:s.game.week,podiums:0,wins:0,seen:{},settled:false};s.funding+=offer.upfront;recordFinance(offer.upfront,`${offer.name} sponsorship`,'Sponsorship');newMail(sender('board'),'Sponsorship signed: '+offer.name,`${money(offer.upfront)} received. ${offer.goal} Bonus: ${money(offer.bonus)}, assessed at the end of the season. One deal per season; no penalty or repayment if you miss the target.`,'info');save();drawFinance()}
function settleSponsor(){const deal=managementState().sponsors[s.game.season];if(!deal||deal.settled)return;deal.settled=true;const met=deal.id==='community'||deal.id==='podium'&&deal.podiums>=3||deal.id==='prestige'&&deal.wins>=1;deal.paidBonus=met?deal.bonus:0;s.funding+=deal.paidBonus;if(deal.paidBonus)recordFinance(deal.paidBonus,`${deal.name} performance bonus`,'Sponsorship');newMail(sender('board'),'Sponsorship review: '+deal.name,`${met?'Target met.':'Target missed.'} Bonus paid: ${money(deal.paidBonus)}. Your upfront funding is retained.`,'review')}
function sponsorshipHTML(){const deal=managementState().sponsors[s.game.season];return `<section class="panel"><div class="panel-h"><strong>Sponsorship</strong><span>One deal per season · signing closes Week 48</span></div><div class="panel-body">${deal?`<h3>${deal.name}</h3><p>${deal.goal}</p><p>Upfront received ${money(deal.upfront)} · Potential bonus ${money(deal.bonus)}<br>Since signing: ${deal.podiums} international podiums / ${deal.wins} wins.</p><p>${deal.settled?'Season settled: '+money(deal.paidBonus)+' bonus paid.':'Bonus assessed when the season ends. No repayment for missing the target.'}</p>`:`<p>Choose guaranteed funding or a larger performance reward. Only results after signing count; national meetings and testing do not count. No repayment if a target is missed.</p><div class="staff-grid">${sponsorOffers().map(x=>`<div class="staff-card"><h3>${x.name}</h3><p>${x.goal}</p><p>${money(x.upfront)} now + ${money(x.bonus)} possible bonus</p><button class="btn secondary" data-sponsor="${x.id}" ${!x.eligible||s.game.week>=48?'disabled':''}>${s.game.week>=48?'SIGNING CLOSED':!x.eligible?'REQUIREMENTS NOT MET':'SIGN DEAL'}</button></div>`).join('')}</div>`}</div></section>`}
function bindStaffActions(){document.querySelectorAll('[data-coach]').forEach(b=>b.onclick=()=>openCoachProfile(b.dataset.coach));document.querySelectorAll('[data-hire]').forEach(b=>b.onclick=()=>appointCoach(b.dataset.role,b.dataset.hire));document.querySelectorAll('[data-renew]').forEach(b=>b.onclick=()=>renewCoach(b.dataset.renew))}
function drawStaff(){ensureCoaches();$('staff').innerHTML=`<div class="section-head"><div><h2>Staff</h2><p>Manage the people responsible for performance, recovery and talent identification.</p></div><button class="btn secondary" id="managerProfileButton">YOUR MANAGER PROFILE</button></div>${staffOverviewHTML()}${coachesHTML()}${coachArchiveHTML()}`;$('managerProfileButton').onclick=openManagerProfile;bindStaffActions()}
function drawFinance(){ensureCoaches();$('finance').innerHTML=`<div class="section-head"><div><h2>Finance & Facilities</h2><p>Control federation resources, sponsorship and long-term programme investment.</p></div><span class="status">${money(s.funding)} available</span></div>${financeOverviewHTML()}<div class="grid2">${financeCommitmentsHTML()}${financeLedgerHTML()}</div><div class="finance-section-spacer"></div>${sponsorshipHTML()}<div class="finance-section-spacer"></div>${facilitiesHTML()}`;document.querySelectorAll('[data-sponsor]').forEach(b=>b.onclick=()=>signSponsor(b.dataset.sponsor));document.querySelectorAll('[data-facility]').forEach(b=>b.onclick=()=>upgradeFacility(b.dataset.facility))}

function upgradeStaff(k){toast('Use staff recruitment to appoint a coach');drawStaff()}
function upgradeFacility(key){if(!Object.hasOwn(FACILITY_DEF,key))return;const level=facilityLevel(key),cost=facilityCost(key);if(level>=5){toast('Already at maximum level');return}if(s.funding<cost){toast('Not enough funding');return}if(!s.facilityLevels)s.facilityLevels=Object.fromEntries(Object.keys(FACILITY_DEF).map(k=>[k,facilityLevel(k)]));s.funding-=cost;recordFinance(-cost,`${FACILITY_DEF[key].name} Level ${level+1}`,'Facilities');s.facilityLevels[key]=level+1;s.facilityHistory??=[];s.facilityHistory.push({key,level:level+1,cost,season:s.game.season,week:s.game.week});newMail(sender('performance'),FACILITY_DEF[key].name+' upgraded',`${FACILITY_DEF[key].name} is now Level ${level+1}. Investment: ${money(cost)}. Remaining budget: ${money(s.funding)}. ${FACILITY_DEF[key].desc}`,'info');save();toast('Facility upgraded');drawFinance()}

function majorEventIntroNeeded(e){return !!(e&&!e.completed&&e.week===s.game.week&&!e.introSeen&&!disciplineRunning&&(e.id==='nationals'||['championship','olympics'].includes(e.kind))&&!Object.values(e.results||{}).some(Array.isArray))}
function enterMajorEvent(e){if(!e||e.completed||e.week!==s.game.week)return;e.introSeen=true;save();competitionMode='overview';drawCompetition()}
function drawMajorEventIntro(e){const olympic=e.kind==='olympics',national=e.id==='nationals',theme=olympic?'olympic':national?'national':'world',discs=e.disc.filter(d=>d!=='ALL'),ids=new Set(eventEntries(e)),squad=s.athletes.filter(a=>ids.has(a.id)&&a.nation===managedNation()&&!a.retired&&a.injury===0),tag=olympic?'THE OLYMPIC STAGE':national?'THE NATIONAL STAGE':'THE WORLD STAGE',line=olympic?'Four years of work. One chance to deliver.':national?'A national title. A chance to be noticed.':'World-class opposition. No easy points.',stakes=olympic?'Olympic medals are on the line. Four years of preparation now comes down to execution.':national?'National titles and ranking points are at stake. Your scouts will also assess athletes outside the current squad.':'Ranking points are available against an international field. This is a clear measure of where your athletes sit right now.';$('competition').innerHTML=`<section class="major-intro major-intro-${theme}" aria-labelledby="majorIntroTitle"><div class="major-intro-scene" aria-hidden="true"><div class="major-intro-track"></div><span>${olympic?'THE GAMES':national?'NATIONALS':'WORLD CUP'}</span></div><div class="major-intro-content"><div class="major-intro-kicker">${tag} • ${s.game.season}</div><h1 id="majorIntroTitle">${profileEscape(e.name)}</h1><p class="major-intro-location">${profileEscape(e.location)} • Week ${e.week} • ${discs.length} disciplines</p><h2>${line}</h2><p class="major-intro-stakes">${stakes}</p><div class="major-intro-team"><div><small>${profileEscape(nationName(managedNation()))}</small><strong>${squad.length} available athlete${squad.length===1?'':'s'} entered</strong></div><span>${squad.length?'Your selected athletes are available to compete.':'You have no available squad entries. Follow the action as a spectator.'}</span></div><div class="major-intro-entries">${squad.map(a=>`<div><strong>${athleteLink(a)}</strong><small>${discLabel(a.disc)} • ${a.fatigue>=60?'High fatigue':a.form>=85?'Strong form':'Ready for competition'}</small></div>`).join('')}</div><div class="major-intro-actions"><button id="enterMajorEvent" class="btn primary">ENTER EVENT DAY →</button><button id="leaveMajorIntro" class="btn ghost">BACK TO HOME</button></div><p class="major-intro-note">Enter Event Day, then start each discipline when you are ready.${eventEntries(e).length?' Your entries require you to complete the event before advancing.':' You can also skip the event from Event Day to view the results.'}</p></div></section>`;$('enterMajorEvent').onclick=()=>enterMajorEvent(e);$('leaveMajorIntro').onclick=()=>view('home')}
function drawCompetition(){let e=currentEvent()||s.events.filter(x=>x.completed&&['competition','championship','olympics','testing'].includes(x.kind)).slice(-1)[0]||s.events.find(x=>!x.completed&&['competition','championship','olympics'].includes(x.kind))||nextEvent();if(!e){$('competition').innerHTML='<div class="panel-body">No event.</div>';return}let live=e.week===s.game.week&&!e.completed,discs=e.disc.filter(d=>d!=='ALL');e.results=e.results||{};let done=discs.filter(x=>Array.isArray(e.results[x]));if(majorEventIntroNeeded(e)){drawMajorEventIntro(e);return}if(competitionMode==='overview'||!discs.length){drawEventOverview(e,live,discs,done);return}if(!activeEventDisc||!discs.includes(activeEventDisc))activeEventDisc=discs[0];drawDisciplineScreen(e,live,discs)}
function drawEventOverview(e,live,discs,done){
 let mn=nationName(managedNation()),totalEntries=eventEntries(e).length,pct=discs.length?Math.round(done.length/discs.length*100):100,status=e.completed?'COMPLETE':live?'LIVE EVENT':`WEEK ${e.week}`;
 let phaseCopy=e.completed?'Every discipline has been completed. Open any card below to review the official result.':live?'Select a discipline to open the premium event presentation. Once a discipline is complete you return here to continue the meeting.':`This event begins in Week ${e.week}. Review your entries, event format and likely pressure points before competition day.`;
 let keyStory=e.kind==='olympics'?'Olympic competition places medals, pressure and programme legacy on the line.':e.kind==='championship'?'Championship day rewards execution. Small margins and selection decisions can define the meeting.':e.ranked?'Ranking points are on offer across the full meeting.':'This is an unranked competition, so the focus is on performance and development rather than points.';
 $('competition').innerHTML=`<div class="event-day-shell"><section class="event-day-hero premium-event-hero"><div class="event-day-brandline"><div class="brandcopy"><small>${e.level} • ${e.kind.toUpperCase()} • EVENT DAY</small><h2>${e.name}</h2><p>${e.location} • ${e.ranked?'Ranked meeting':'Unranked meeting'} • ${discs.length} discipline${discs.length===1?'':'s'} • ${keyStory}</p></div><div class="event-status-cluster"><div class="event-status-chip"><i></i> ${status}</div><strong>${done.length}/${discs.length}</strong><span>${e.completed?'Official results confirmed':live?'Disciplines complete':'Meeting progress'}</span></div></div><div class="event-day-meta premium-event-meta"><div class="metric"><small>Venue</small><strong>${e.location}</strong></div><div class="metric"><small>${mn} entries</small><strong>${totalEntries}</strong></div><div class="metric"><small>Disciplines</small><strong>${discs.length}</strong></div><div class="metric"><small>Meeting state</small><strong>${e.completed?'Finished':live?'In progress':'Preview'}</strong></div></div><div class="event-day-progress-wrap"><div class="event-progress"><i style="width:${pct}%"></i></div></div></section><div class="event-programme-grid"><section class="event-programme-card"><div class="event-programme-head"><div><div class="page-kicker">Competition programme</div><h3>${e.completed?'Official meeting summary':live?'Choose the next discipline':'Pre-meet briefing'}</h3><p>${phaseCopy}</p></div><div class="event-programme-tag"><small>Completion</small><strong>${pct}%</strong></div></div><div class="event-discipline-grid event-discipline-premium">${discs.map(d=>{let r=e.results[d],isDone=Array.isArray(r),ids=e.entries[d]||[],own=ids.map(id=>s.athletes.find(a=>a.id===id)).filter(Boolean),winner=isDone?r[0]:null,cardStatus=isDone?'Complete':live?'Ready':'Scheduled',statusClass=isDone?'good':live?'live':'',family=DISCIPLINES[d].type==='time'?'Track discipline':'Field discipline';return`<section class="event-disc-card event-disc-premium ${isDone?'complete':''}"><div class="disc-top"><div><div class="page-kicker">${family}</div><h3>${discLabel(d)}</h3></div><span class="status ${statusClass}">${cardStatus}</span></div><div class="event-disc-meta"><span>${own.length?own.length+' '+(own.length===1?'entry':'entries'):'No entry'}</span><span>${e.engine?.[d]?.format||athleticsFormat(e,d).format||'Standard format'}</span></div><div class="disc-entry">${own.length?`${mn}: ${own.map(a=>athleteLink(a)).join(', ')}`:`No ${mn} athlete selected`}</div><div class="disc-result">${isDone&&!winner?`<small>No result</small><strong>No starters</strong>`:isDone?`<small>Winner</small><strong>${winner.flag} ${athleteLink(s.athletes.find(a=>a.id===winner.id),winner.name)} • ${fmtPerf(d,winner.perf)}</strong>`:`<small>Event status</small><strong>${live?'Ready for broadcast start':'Starts Week '+e.week}</strong>`}</div><div class="event-disc-action"><button class="btn ${isDone?'good':live?'primary':'ghost'}" data-event-disc="${d}" ${!isDone&&!live?'disabled':''}>${isDone?'VIEW RESULT':live?'OPEN '+discLabel(d).toUpperCase():'EVENT LOCKED'}</button></div></section>`}).join('')}</div></section><aside class="event-side-stack"><section class="event-side-card"><div class="panel-h"><strong>Meeting brief</strong><span>At a glance</span></div><div class="panel-body"><div class="event-bullet-list"><div><small>Broadcast flow</small><strong>${live?'Open a discipline, watch or simulate it, then return here for the next decision.':'Event Day will activate automatically when competition week arrives.'}</strong></div><div><small>Management focus</small><strong>${totalEntries?`${totalEntries} ${mn} entr${totalEntries===1?'y is':'ies are'} part of the meeting.`:`No ${mn} athletes are entered. You can still follow the meeting as a spectator.`}</strong></div><div><small>Current priority</small><strong>${e.completed?'Review the completed results and podiums.':live?'Keep the meeting moving and decide which discipline gets the spotlight next.':e.ranked?'Plan for ranking points and performance management before event week.':'Use this meeting to judge readiness and development.'}</strong></div></div>${live&&!totalEntries?'<div style="margin-top:12px"><button id="skipEvent" class="btn ghost" style="width:100%">SKIP EVENT • VIEW RESULTS</button></div>':''}</div></section><section class="event-side-card"><div class="panel-h"><strong>Production note</strong><span>Presentation</span></div><div class="panel-body"><div class="event-side-note">The Event Day screen now uses a tighter broadcast-style layout so the live visual, commentary and discipline programme feel like one premium package rather than separate widgets on the page.</div></div></section></aside></div></div>`;
 document.querySelectorAll('[data-event-disc]').forEach(b=>b.onclick=()=>{let d=b.dataset.eventDisc;if(Array.isArray(e.results[d])){activeEventDisc=d;competitionMode='discipline';drawCompetition()}else startDiscipline(e,d)});
 if($('skipEvent'))$('skipEvent').onclick=()=>skipEvent(e)
}
let liveEventView=null;
function nationDotColour(n){const colours={'GREAT BRITAIN':'#ef3340',USA:'#408dff',JAMAICA:'#ffd84a',GERMANY:'#ff8a35',KENYA:'#46ca73',ETHIOPIA:'#7bde54',CANADA:'#ff6881',FRANCE:'#ae9aff',JAPAN:'#f1f5f9',CHINA:'#ff6060',AUSTRALIA:'#e6d653',BRAZIL:'#4bd6ac'};if(colours[n])return colours[n];let hash=0;for(const ch of String(n))hash=(hash*31+ch.charCodeAt(0))>>>0;return ['#69cde8','#e9a1e9','#aad971','#ffc081'][hash%4]}
function visualPhase(line){const h=String(line||'').split('\n')[0];if(/^(RESULT|PERFORMANCE WATCH|YOUR SQUAD)/.test(h))return {progress:1,finished:true,label:'Official result',stage:'result'};const m=h.match(/^(20|40|60|80|100) METRES/);if(m)return {progress:Number(m[1])/100,finished:false,label:h,stage:Number(m[1])===100?'finish':'race'};if(h.startsWith('SET'))return {progress:.055,finished:false,label:'The gun',stage:'gun'};if(h.startsWith('ON YOUR MARKS'))return {progress:.008,finished:false,label:'On your marks',stage:'blocks'};return {progress:0,finished:false,label:h||'Waiting for the start',stage:'build'} }
function fieldVisualPhase(line,type){const h=String(line||'').split('\n')[0];if(/^(RESULT|PERFORMANCE WATCH|YOUR SQUAD)/.test(h))return {stage:'result',finished:true,label:'Official result'};if(type==='height'){if(h.startsWith('AT THE APRON'))return {stage:'apron',label:h};if(h.startsWith('THE APPROACH'))return {stage:'approach',label:h};if(h.startsWith('AT THE BAR'))return {stage:'flight',label:h};if(h.startsWith('PRESSURE BUILDING'))return {stage:'pressure',label:h};if(h.startsWith('THE FINAL MARKS'))return {stage:'final',label:h}}else{if(h.startsWith('IN THE CIRCLE'))return {stage:'circle',label:h};if(h.startsWith('POWER AND CONTROL'))return {stage:'power',label:h};if(h.startsWith('OUT INTO THE SECTOR'))return {stage:'flight',label:h};if(h.startsWith('THE CONTEST DEVELOPS'))return {stage:'pressure',label:h};if(h.startsWith('THE FINAL MEASUREMENTS'))return {stage:'final',label:h}}return {stage:'build',finished:false,label:h||'Waiting for the field'} }
