  const summit=summitMeetings().filter(m=>!m.completed&&m.week>=start&&m.week<=end&&m.entries.includes(a.id)).map(m=>'Summit Series '+m.number+' (W'+m.week+')');
  return [...new Set([...base,...summit])];
