bookPlan=function(kind,type,ids,week){
  const c=CAMP_OPTIONS[type],end=week+(kind==='camp'?c.weeks:1)-1,cost=kind==='camp'?c.cost*ids.length:0;
  if(!ids.length||week<s.game.week||end>52||cost>s.funding)return;
  for(const id of ids){
    const a=s.athletes.find(a=>a.id===id);
    if(kind==='camp'&&week===s.game.week&&s.events.some(e=>e.week===week&&Object.values(e.results||{}).some(r=>Array.isArray(r)&&r.some(x=>x.id===id)))){toast('This athlete already competed; book camp from next week');return}
    const summitConflict=summitMeetings().find(m=>!m.completed&&m.week>=week&&m.week<=end&&m.entries.includes(id));
    if(!a||a.retired||a.inSquad===false||a.nation!==managedNation()||a.injury>0||planOverlap(id,week,end)||(a.camp&&a.camp.until>careerNow()+week-s.game.week)||summitConflict){
      toast(summitConflict?'This athlete is registered for Summit Series '+summitConflict.number:'An athlete is unavailable or has an overlapping commitment');return
    }
  }
  s.funding-=cost;
  const p={id:'plan-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),season:s.game.season,week,kind,type,ids,status:'scheduled',cost};planList().push(p);
  if(kind==='camp')for(const e of s.events.filter(e=>!e.completed&&e.week>=week&&e.week<=end))for(const d of Object.keys(e.entries))e.entries[d]=e.entries[d].filter(id=>!ids.includes(id));
  if(week===s.game.week&&kind==='camp')startPlannedCamps();
  save();drawCalendar();toast(kind==='camp'?'Camp booked':'Testing day booked; runs when this week advances');
};
