  if(tired.length>=2)return {plan:'Recovery',title:'Freshen the group before you chase gains',text:`${tired.length} squad athletes are already carrying fatigue of 60 or more. The performance team would begin with recovery, then reassess after the first weekly report.`};
  if(field.length&&fieldForm<80)return {plan:'Technique',title:'Sharpen the technical events',text:'The jumps and throws group has the clearest early form gap. A technical week gives those athletes the most targeted opening intervention.'};
