function editorialCleanSavedText(value){
 if(typeof value!=='string')return value;
 return value
  .replace(/<strong>Storyline:<\/strong>\s*/gi,'<strong>Background:</strong> ')
  .replace(/Story context:\s*/gi,'')
  .replace(/This medical chapter interrupts an existing storyline:\s*/gi,'Recent competition note: ')
  .replace(/closes the first chapter of the rehabilitation story\. The next question is whether competitive form can now be rebuilt\./gi,'marks a successful return to competition. The focus now is rebuilding form.')
  .replace(/The result gives the earlier call-up a new meaning: this is no longer only a development story\./gi,'The result strengthens the case that the call-up was justified.')
  .replace(/The decision to bring ([^.!]+) out of the National Pool has now produced a win at ([^.!]+)\. Keep judging the athlete on current evidence, but the pathway decision is beginning to carry real weight\./gi,'The call-up of $1 has now produced a win at $2. Keep judging the place on current performance and readiness.')
  .replace(/adds another chapter/gi,'adds another close meeting')
  .replace(/the story is building week by week/gi,'the return is progressing week by week')
  .replace(/story is still being written by selection, preparation and results/gi,'has no major career development to report yet')
  .replace(/This opening chapter is guidance, not a locked tutorial\./gi,'This guide is optional.')
  .replace(/story thread/gi,'opening guide')
  .replace(/Key chapters/gi,'Recent milestones')
  .replace(/CURRENT STORYLINE/gi,'CAREER WATCH');
}
