const SQUAD_AGREEMENT_TERMS=[10,20,30,40,52];
function agreementEndLabel(absWeek){const n=Math.max(1,Number(absWeek)||careerNow()),currentCareerYear=careerState?.().careerYear||Math.floor((careerNow()-1)/52)+1,careerStartSeason=s.game.season-currentCareerYear+1,targetCareerYear=Math.floor((n-1)/52)+1,week=(n-1)%52+1,season=careerStartSeason+targetCareerYear-1;return `${season} • Week ${week}`}
function squadAgreementRemaining(a){if(!a||a.inSquad===false||!a.squadAgreement)return 0;return Math.max(0,Math.ceil((Number(a.squadAgreement.endCareerWeek)||0)-careerNow()))}
function squadAgreementText(a){const ag=a?.squadAgreement;if(!ag||a.inSquad===false)return '';const left=squadAgreementRemaining(a);return `National Squad Agreement: ${left} week${left===1?'':'s'} remaining • ends ${agreementEndLabel(ag.endCareerWeek)}`}
// Preserve the existing profile hooks, but make them contract-aware.
