squadCommitText=function(a){return squadAgreementText(a)};
function ensureAthleteAgreements(){if(!s?.athletes)return;const now=careerNow();for(const a of s.athletes){if(a.nation!==managedNation()||a.retired||a.inSquad===false)continue;if(!a.squadAgreement||!Number.isFinite(Number(a.squadAgreement.endCareerWeek))||Number(a.squadAgreement.endCareerWeek)<=now){a.squadAgreement={startCareerWeek:now,endCareerWeek:now+52,termWeeks:52,reminderForEnd:null,history:[{careerWeek:now,type:'migration',weeks:52}]};a.squadJoinedCareerWeek??=now}a.squadCommitUntil=0}}
function withdrawFutureSquadEntries(a){for(const e of s.events.filter(e=>!e.completed)){for(const d of Object.keys(e.entries||{})){const before=e.entries[d]||[];if(before.includes(a.id)){e.entries[d]=before.filter(x=>x!==a.id);e.decision=false}}}}
function returnAgreementToPool(a,reason='agreement expired'){if(!a||a.retired||a.inSquad===false)return;a.staffKnowledgeFloor=Math.max(Number(a.staffKnowledgeFloor)||0,athleteAssessmentKnowledge(a));a.inSquad=false;a.poolEnteredCareerWeek=careerNow();withdrawFutureSquadEntries(a);const ag=a.squadAgreement;if(ag){ag.status='expired';ag.expiredCareerWeek=careerNow();ag.history??=[];ag.history.push({careerWeek:careerNow(),type:'expired'})}rememberAthlete(a,'Squad agreement',`National Squad Agreement ${reason}. Returned to the National Pool.`);addNews('Federation',`${a.name} returns to ${nationName(managedNation())} National Pool`,`${discLabel(a.disc)} • squad agreement ended`,`${a.name}'s National Squad Agreement has ended. The athlete returns to the National Pool and a senior squad place is now available.`,{nation:managedNation(),athleteId:a.id});newMail(sender('performance'),`Squad agreement ended: ${a.name}`,`${a.name}'s National Squad Agreement has expired. The athlete has automatically returned to the National Pool and future senior-squad entries have been withdrawn.`,'review')}
function squadAgreementReminderHTML(a){const ag=a.squadAgreement,left=squadAgreementRemaining(a);return `<div class="mail-section"><h3>National Squad Agreement</h3><p><strong>${profileEscape(a.name)}</strong> has ${left} week${left===1?'':'s'} remaining on the current agreement, which ends ${profileEscape(agreementEndLabel(ag.endCareerWeek))}.</p><p>Extend the agreement below, or take no action and the athlete will automatically return to the National Pool when it expires. There is no funding cost.</p></div><div class="mail-section"><h3>Extension options</h3><div class="staff-grid">${SQUAD_AGREEMENT_TERMS.map(w=>`<button class="btn secondary" data-squad-agreement-extend="${a.id}" data-agreement-weeks="${w}" data-agreement-end="${ag.endCareerWeek}">+${w} WEEKS</button>`).join('')}</div></div>`}
function sendSquadAgreementReminder(a){const ag=a.squadAgreement;if(!ag||ag.reminderForEnd===ag.endCareerWeek)return;ag.reminderForEnd=ag.endCareerWeek;const id=newMail(sender('performance'),`Squad agreement decision: ${a.name}`,`${a.name}'s National Squad Agreement has two weeks remaining. Extend the term or allow it to expire and return the athlete to the National Pool.`,'review'),m=s.emails.find(x=>x.id===id);if(m){m.squadAgreementAthleteId=a.id;m.squadAgreementEnd=ag.endCareerWeek;m.html=squadAgreementReminderHTML(a)}}
function extendSquadAgreement(id,weeks,expectedEnd){const a=s.athletes.find(x=>x.id===id),term=Number(weeks);if(!a||a.retired||a.nation!==managedNation()||a.inSquad===false||!a.squadAgreement){toast('This athlete is no longer in the senior squad');return false}if(!SQUAD_AGREEMENT_TERMS.includes(term)){toast('Invalid agreement term');return false}if(Number(expectedEnd)!==Number(a.squadAgreement.endCareerWeek)){toast('This agreement has already changed');return false}a.squadAgreement.endCareerWeek+=term;a.squadAgreement.termWeeks=term;a.squadAgreement.history??=[];a.squadAgreement.history.push({careerWeek:careerNow(),type:'extension',weeks:term,newEnd:a.squadAgreement.endCareerWeek});a.squadAgreement.reminderForEnd=null;rememberAthlete(a,'Squad agreement',`National Squad Agreement extended by ${term} weeks.`);const m=s.emails.find(x=>x.id===openMail);if(m?.squadAgreementAthleteId===a.id){m.body=`Agreement extended by ${term} weeks. New end: ${agreementEndLabel(a.squadAgreement.endCareerWeek)}.`;m.html=`<div class="mail-section"><h3>Agreement extended</h3><p>${profileEscape(a.name)} will remain in the senior squad for another ${term} weeks. The new agreement end is <strong>${profileEscape(agreementEndLabel(a.squadAgreement.endCareerWeek))}</strong>.</p><p>No funding cost applies.</p></div>`}save();toast(`${a.name} extended • +${term} weeks`);drawInbox();return true}
function processSquadAgreements(){ensureAthleteAgreements();const now=careerNow();for(const a of [...s.athletes]){if(a.nation!==managedNation()||a.retired||a.inSquad===false||!a.squadAgreement)continue;const left=squadAgreementRemaining(a);if(left<=0){returnAgreementToPool(a,'expired');continue}if(left<=2&&a.squadAgreement.reminderForEnd!==a.squadAgreement.endCareerWeek)sendSquadAgreementReminder(a)}save()}
function finaliseSquadAgreementCallUp(id,term){const a=s.athletes.find(x=>x.id===id),weeks=Number(term);if(!a||a.retired||a.nation!==managedNation()||a.inSquad!==false)return false;if(managedTeam().length>=SQUAD_LIMIT){toast('National squad is full');return false}if(!SQUAD_AGREEMENT_TERMS.includes(weeks))return false;a.staffKnowledgeFloor=Math.max(Number(a.staffKnowledgeFloor)||0,athleteAssessmentKnowledge(a));const now=careerNow();a.squadJoinedCareerWeek=now;a.squadCommitUntil=0;a.squadAgreement={startCareerWeek:now,endCareerWeek:now+weeks,termWeeks:weeks,reminderForEnd:null,status:'active',history:[{careerWeek:now,type:'call-up',weeks}]};rememberAthlete(a,'Call-up',`Promoted from the National Pool on a ${weeks}-week National Squad Agreement.`);a.inSquad=true;if(a.tier==='National Pool')a.tier=a.age<=21?'Prospect':'Developing';addNews('Federation',`${a.name} earns ${nationName(managedNation())} call-up`,`${discLabel(a.disc)} • ${weeks}-week squad agreement`,`${a.name} has been promoted from the National Pool into the national squad on a ${weeks}-week agreement. The performance team will continue building its assessment while the athlete works at senior level.`,{nation:managedNation(),athleteId:a.id});newMail(sender('performance'),`Squad agreement confirmed: ${a.name}`,`${a.name} has joined the senior squad on a ${weeks}-week National Squad Agreement, ending ${agreementEndLabel(a.squadAgreement.endCareerWeek)}. There is no funding cost. A renewal decision will be sent two weeks before expiry.`,'review');save();selectedAthlete=id;squadTab='squad';toast(`${a.name} called up • ${weeks}-week agreement`);return true}
function openSquadAgreementChooser(id){const a=s.athletes.find(x=>x.id===id);if(!a||a.retired||a.nation!==managedNation()||a.inSquad!==false)return;if(managedTeam().length>=SQUAD_LIMIT){toast('National squad is full');return}if($('athleteProfile')?.open)$('athleteProfile').close();managementDialog(`Call up ${a.name}`,`<section class="profile-panel"><div class="profile-kicker">NATIONAL SQUAD AGREEMENT</div><h2>Choose the commitment</h2><p>Calling ${profileEscape(a.name)} into the senior squad uses one of your ${SQUAD_LIMIT} squad places for the full agreement. There is no salary or funding cost.</p><p>Two weeks before expiry, the performance team will ask whether you want to extend. If you do nothing, the athlete automatically returns to the National Pool.</p></section><div class="staff-grid">${[[10,'Short assessment'],[20,'Half-season block'],[30,'Development block'],[40,'Core season'],[52,'Full year']].map(([w,label])=>`<div class="staff-card"><h3>${w} weeks</h3><p>${label}<br>Ends ${profileEscape(agreementEndLabel(careerNow()+w))}</p><button class="btn secondary" data-agreement-callup="${a.id}" data-agreement-weeks="${w}">SELECT ${w} WEEKS</button></div>`).join('')}</div>`);document.querySelectorAll('[data-agreement-callup]').forEach(b=>b.onclick=()=>{if(finaliseSquadAgreementCallUp(b.dataset.agreementCallup,Number(b.dataset.agreementWeeks))){$('managementProfile').close();renderView(currentView);openAthleteProfile(id)}})}
// Replace legacy call-up/drop behaviour with agreement-based squad membership.
callUpToSquad=function(id){openSquadAgreementChooser(id)};
dropFromSquad=function(id){const a=s.athletes.find(x=>x.id===id);if(!a||a.retired||a.nation!==managedNation()||a.inSquad===false)return;const left=squadAgreementRemaining(a);if(left>0){toast(`${a.name}'s squad agreement has ${left} week${left===1?'':'s'} remaining`);return}returnAgreementToPool(a,'ended');save();renderView(currentView)};
const _agreementOnWeekStart=onWeekStart;
onWeekStart=function(){_agreementOnWeekStart();processSquadAgreements()};
