    const h=hashString(`${a.id}|${a.name}|independence`),p=visualProfileForNation(a.nation),female=(h%2)===0,firsts=female?(p.femaleFirst||VISUAL_NAME_POOLS.DEFAULT.femaleFirst):(p.maleFirst||VISUAL_NAME_POOLS.DEFAULT.maleFirst),lasts=p.surnames||VISUAL_NAME_POOLS.DEFAULT.surnames;
