function requestOpen(a){const r=independenceState(a)?.request;return !!(r&&r.status==='pending')}
function independenceMajorAhead(a){return s.events.filter(e=>!e.completed&&e.week>=s.game.week&&e.week<=s.game.week+8&&(e.kind==='championship'||e.kind==='olympics')&&(e.disc.includes(a.disc)||e.disc.includes('ALL'))).sort((x,y)=>x.week-y.week)[0]||null}
