   if(major&&summit&&st.championship==='Protect the build'&&Math.random()<.55){if(createAthleteRequest(a,{type:'protect',targetKind:'summit',targetNumber:summit.number,targetName:`Summit Series ${summit.number}`,targetWeek:summit.week,majorName:major.name}))return}
   if(st.competition==='Active'&&summit){if(createAthleteRequest(a,{type:'compete',targetKind:'summit',targetNumber:summit.number,targetName:`Summit Series ${summit.number}`,targetWeek:summit.week}))return}
