function targetWasEntered(a,r){if(r.targetKind==='summit'){const m=s.summitSeries?.[s.game.season]?.meetings?.[r.targetNumber];return !!m?.entries?.includes(a.id)||!!m?.results&&Object.values(m.results).some(rows=>Array.isArray(rows)&&rows.some(x=>x.id===a.id))}const e=s.events.find(x=>x.id===r.targetId);return !!Object.values(e?.entries||{}).some(ids=>(ids||[]).includes(a.id))||!!Object.values(e?.results||{}).some(rows=>Array.isArray(rows)&&rows.some(x=>x.id===a.id))}
