  const sprint=blueprint?blueprint.sprint:clamp(Math.round(52+(sprintTalent-72)*2+(seed%9-4)),42,90),field=blueprint?blueprint.field:clamp(Math.round(52+(fieldTalent-72)*2+((seed>>>4)%9-4)),42,90),pathway=blueprint?blueprint.pathway:clamp(Math.round(54+(youngTalent-70)*1.7+((seed>>>8)%9-4)),45,88);
  const level=v=>clamp(Math.round((v-35)/13),1,5),fac=blueprint?{...blueprint.facilities}:{sprint:level(sprint),field:level(field),recovery:clamp(1+((seed>>>12)%3),1,3)},staff=blueprint?{sprint:blueprint.staff.sprint,field:Math.round((blueprint.staff.jumps+blueprint.staff.throws)/2),pathway:blueprint.staff.scout,science:blueprint.staff.science}:{sprint:level(sprint),field:level(field),pathway:level(pathway),science:clamp(1+((seed>>>15)%3),1,3)};
  return {nation,strategy:RIVAL_PROGRAMME_STRATEGIES[seed%RIVAL_PROGRAMME_STRATEGIES.length],budget:Math.round(2200000+(sprint+field+pathway)*9000),sprint,field,pathway,facilities:fac,staff,headCoach:rivalCoachName(nation,seed),generation:'Competitive',generationScore:78,momentum:0,lastInvestmentSeason:0,lastCoachChangeSeason:0,history:[]}
