function rivalProgrammeInvestment(p){const choices=[{type:'facility',key:'sprint',level:p.facilities.sprint,weight:(p.strategy==='Circuit-active'?3:1)+(p.sprint>=p.field?1:0)},{type:'facility',key:'field',level:p.facilities.field,weight:1+(p.field>p.sprint?1:0)},{type:'facility',key:'recovery',level:p.facilities.recovery,weight:p.strategy==='Championship-first'?3:1},{type:'staff',key:'sprint',level:p.staff.sprint,weight:p.sprint>=p.field?2:1},{type:'staff',key:'field',level:p.staff.field,weight:p.field>p.sprint?2:1},{type:'staff',key:'pathway',level:p.staff.pathway,weight:p.strategy==='Pathway-led'?4:1},{type:'staff',key:'science',level:p.staff.science,weight:p.strategy==='Championship-first'?3:1}].filter(x=>x.level<5);if(!choices.length)return null;choices.sort((a,b)=>(a.level/(a.weight||1))-(b.level/(b.weight||1))||hashString(`${p.nation}:${s.game.season}:${a.type}:${a.key}`)-hashString(`${p.nation}:${s.game.season}:${b.type}:${b.key}`));const pick=choices[0],cost=500000+pick.level*260000;if(p.budget<cost)return null;p.budget-=cost;if(pick.type==='facility')p.facilities[pick.key]++;else p.staff[pick.key]++;p.lastInvestmentSeason=s.game.season;const label=pick.key==='sprint'?'sprint programme':pick.key==='field'?'field-event programme':pick.key==='recovery'?'recovery infrastructure':pick.key==='pathway'?'talent pathway':'sports-science support';p.history.push({season:s.game.season,type:'investment',text:`Investment raised ${label} to Level ${pick.type==='facility'?p.facilities[pick.key]:p.staff[pick.key]}.`});return {label,level:pick.type==='facility'?p.facilities[pick.key]:p.staff[pick.key],cost}}
