function updateRivalProgrammesAnnual(){const rw=rivalWorldState();if(rw.lastAnnualSeason===s.game.season)return;rw.lastAnnualSeason=s.game.season;const standings=nationRanks(),stories=[];for(const n of Object.keys(COUNTRIES).filter(n=>n!==managedNation())){const p=rivalProgramme(n),rank=Math.max(1,standings.findIndex(x=>x[0]===n)+1),oldGen=p.generation,oldStrategy=p.strategy,identity=NATIONS[n]?nationalIdentityState(n):null;if(identity){p.sprint=Math.round(p.sprint*.65+identity.sprint*.35);p.field=Math.round(p.field*.65+identity.field*.35);p.pathway=Math.round(p.pathway*.65+identity.pathway*.35)}else{const sprintTalent=rivalAthleteAverage(n,a=>isSprintDiscipline(a.disc),4,74),fieldTalent=rivalAthleteAverage(n,a=>!isSprintDiscipline(a.disc),6,74),youngTalent=rivalAthleteAverage(n,a=>a.age<=23,5,72);p.sprint=Math.round(p.sprint*.78+clamp(48+(sprintTalent-70)*1.8,40,92)*.22);p.field=Math.round(p.field*.78+clamp(48+(fieldTalent-70)*1.8,40,92)*.22);p.pathway=Math.round(p.pathway*.82+clamp(50+(youngTalent-68)*1.6,42,92)*.18)}const annualGrant=1800000+Math.max(0,9-rank)*180000+Math.round((p.sprint+p.field+p.pathway)*3500);p.budget=Math.min(14000000,p.budget+annualGrant);const investment=rivalProgrammeInvestment(p);evolveRivalAthletesAnnual(n,p);const active=s.athletes.filter(a=>!a.retired&&a.nation===n).length;if(active<20&&Math.random()<.55+(p.staff.pathway||1)*.06)newProspect(n);if((s.game.cycleYear===4||rank>8)&&Math.random()<.22){const options=RIVAL_PROGRAMME_STRATEGIES.filter(x=>x!==p.strategy);p.strategy=options[hashString(`${n}:${s.game.season}:strategy`)%options.length];p.history.push({season:s.game.season,type:'strategy',text:`Federation shifted from ${oldStrategy} to ${p.strategy}.`})}const gen=rivalGeneration(n);p.generation=gen.label;p.generationScore=gen.score;p.momentum=clamp((p.momentum||0)+(rank<=3?4:rank>=9?-3:1),-20,20);p.history=p.history.slice(-20);if(oldGen&&oldGen!==gen.label)stories.push({priority:Math.abs(gen.score-(p.previousGenerationScore||gen.score))>=5?2:1,n,headline:gen.label==='Golden generation'?`${nationName(n)} talent wave raises expectations`:gen.label==='Strong generation'?`${nationName(n)} enters a stronger competitive phase`:gen.label==='Rebuilding'?`${nationName(n)} programme enters rebuild`:gen.label==='Thin pipeline'?`${nationName(n)} facing a thinner talent cycle`:`${nationName(n)} generation stabilises`,deck:`${flag(n)} ${p.strategy} • ${gen.label}`,body:`The ${nationName(n)} programme now profiles as ${gen.label.toLowerCase()}. Federation investment, pathway output and the current athlete generation have shifted the competitive outlook entering the next season.`});else if(investment&&investment.level>=4)stories.push({priority:1,n,headline:`${nationName(n)} invests in ${investment.label}`,deck:`Federation programme reaches Level ${investment.level}`,body:`The ${nationName(n)} federation has committed resources to its ${investment.label}. The investment forms part of a ${p.strategy.toLowerCase()} programme strategy and will influence preparation and athlete development over future seasons.`});p.previousGenerationScore=gen.score}stories.sort((a,b)=>b.priority-a.priority||hashString(`${s.game.season}:${a.n}`)-hashString(`${s.game.season}:${b.n}`)).slice(0,2).forEach(x=>addNews('Federation',x.headline,x.deck,x.body,{nation:x.n,priority:x.priority>1?'major':'normal'}))}
function maybeRivalProgrammeWeeklyNews(){const rw=rivalWorldState(),cw=careerNow();if(cw-rw.lastProgrammeNews<9||Math.random()>.045)return;const nations=Object.keys(COUNTRIES).filter(n=>n!==managedNation()),n=nations[rint(0,nations.length-1)],p=rivalProgramme(n),area=['sprint','field','pathway','science'][rint(0,3)],old=p.staff[area]||1,delta=Math.random()<.72?1:-1,next=clamp(old+delta,1,5);if(next===old)return;p.staff[area]=next;p.lastCoachChangeSeason=s.game.season;const oldCoach=p.headCoach;p.headCoach=rivalCoachName(n,hashString(`${n}:${cw}:coach`));rw.lastProgrammeNews=cw;const dept=area==='sprint'?'sprint':area==='field'?'field events':area==='pathway'?'athlete pathway':'sports science';addNews('Federation',`${nationName(n)} reshuffles ${dept} leadership`,`${flag(n)} ${oldCoach} → ${p.headCoach}`,`${nationName(n)} has changed leadership within its ${dept} programme. ${p.headCoach} takes the role as the federation continues with a ${p.strategy.toLowerCase()} strategy. Internal coaching strength has ${next>old?'improved':'dropped'} from Level ${old} to Level ${next}.`,{nation:n,priority:next>old&&next>=4?'major':'normal'});p.history.push({season:s.game.season,week:s.game.week,type:'coach',text:`${dept} leadership changed: ${oldCoach} replaced by ${p.headCoach}.`});p.history=p.history.slice(-20)}
