function summitProxy(m){const entries={};Object.keys(DISCIPLINES).forEach(d=>entries[d]=summitEntriesForDisc(m,d).map(a=>a.id));if(!summitLiveProxy||summitLiveProxy.number!==m.number||summitLiveProxy.season!==s.game.season)summitLiveProxy={number:m.number,season:s.game.season,id:'summit-live-'+s.game.season+'-'+m.number,name:'Summit Series '+m.number,location:m.location,kind:'competition',level:'Summit Series',week:m.week,ranked:false,disc:Object.keys(DISCIPLINES),entries,results:m.results,commentary:m.commentary??={}};summitLiveProxy.entries=entries;summitLiveProxy.results=m.results;summitLiveProxy.commentary=m.commentary??={};return summitLiveProxy}
function summitMast(m,done){return `<div class="summit-live-mast"><div class="summit-live-brand"><div class="summit-live-mark"></div><div><small>SUMMIT SERIES • ${s.game.season}</small><h2>SUMMIT SERIES ${m.number}</h2></div><div class="summit-live-round"><small>ROUND</small><strong>${m.number} / 6</strong></div></div><div class="summit-live-meta"><div><small>Venue</small><strong>${profileEscape(m.location)}</strong></div><div><small>Week</small><strong>${m.week}</strong></div><div><small>Programme</small><strong>${done}/${Object.keys(DISCIPLINES).length} complete</strong></div><div><small>Series roster</small><strong>${summitSeasonState().seriesEntries.length}</strong></div></div></div>`}
function summitReadyVisual(m,d){const field=summitField(m,d);return `<div class="live-arena"><div class="live-arena-head"><span>Summit field ready • ${profileEscape(discLabel(d))}</span></div><div class="live-arena-stage" style="display:grid;place-items:center;min-height:250px;background:radial-gradient(circle at 50% 35%,#8a70e633,transparent 34%),linear-gradient(145deg,#0c1630,#07101d)"><div style="text-align:center"><div style="font-size:42px;color:#c7b8ff">▲</div><strong style="display:block;font-size:22px;margin-top:8px">SUMMIT SERIES ${m.number}</strong><span style="display:block;color:#8798ad;font-size:10px;margin-top:7px">${field.length} athletes ready</span></div></div><div class="live-arena-legend">${field.map((a,i)=>`<span><i style="background:${nationDotColour(a.nation)}"></i>${DISCIPLINES[d].type==='time'?'Lane '+(i+1)+' • ':''}${profileEscape(a.name)} · ${profileEscape(nationName(a.nation))}</span>`).join('')}</div></div>`}
function drawSummitArrival(m){$('pageKicker').textContent='SUMMIT SERIES';$('pageTitle').textContent='Series '+m.number+' • '+m.location;$('competition').innerHTML=`<div class="summit-live-shell">${summitMast(m,0)}<div class="summit-live-body"><div class="summit-series-lock-note"><strong>Full-Series commitment:</strong> the roster below is locked into every Summit round and unavailable for all other competition until Series 6 ends.</div><div class="summit-live-choice"><button id="watchSummit" class="primary"><small>SUMMIT EVENT DAY</small><strong>Watch Meeting</strong><span>Run the full meeting programme with the Summit Series presentation, live visuals and commentary.</span><b>WATCH SUMMIT SERIES →</b></button><button id="simSummit"><small>FAST FORWARD</small><strong>Simulate Meeting</strong><span>Resolve the full round instantly with the same fields and performance engine, then review the official Series results.</span><b>SIMULATE ROUND →</b></button></div></div></div>`;$('watchSummit').onclick=()=>{m.eventDayMode='watch';competitionMode='overview';save();drawCompetition()};$('simSummit').onclick=()=>{m.eventDayMode='simulate';simulateSummitMeeting(m);competitionMode='overview';save();render()}}
function drawSummitOverviewLive(m){const discs=Object.keys(DISCIPLINES),done=discs.filter(d=>Array.isArray(m.results?.[d])),remaining=discs.length-done.length;$('pageKicker').textContent='SUMMIT SERIES';$('pageTitle').textContent='Series '+m.number+' • '+m.location;$('competition').innerHTML=`<div class="summit-live-shell">${summitMast(m,done.length)}<div class="summit-live-body">${m.completed?`<div class="summit-series-complete-banner"><strong>Summit Series ${m.number} complete</strong><span>Series points are confirmed. ${m.number===6?'The six-meeting commitment is now finished.':'The same roster remains committed for the next round.'}</span></div>`:`<div class="summit-live-toolbar"><div><strong>SUMMIT PROGRAMME</strong><span>${done.length}/${discs.length} disciplines complete • ${remaining} remaining</span></div><button id="simSummitRemaining" class="btn ghost">SIMULATE REMAINING</button></div>`}<div class="event-discipline-grid">${discs.map(d=>{const r=m.results[d],complete=Array.isArray(r),winner=complete?r[0]:null,own=summitEntriesForDisc(m,d);return `<section class="event-disc-card ${complete?'complete':''}"><div class="disc-top"><div><div class="page-kicker">${DISCIPLINES[d].type==='time'?'SUMMIT TRACK':'SUMMIT FIELD'}</div><h3>${discLabel(d)}</h3></div><span class="status ${complete?'good':'live'}">${complete?'COMPLETE':'READY'}</span></div><div class="disc-entry">${own.length?`${nationName(managedNation())}: ${own.map(a=>athleteLink(a)).join(', ')}`:`No ${nationName(managedNation())} entry`}</div><div class="disc-result">${winner?`<small>Round winner</small><strong>${flag(winner.nation)} ${profileEscape(winner.name)} • ${fmtPerf(d,winner.perf)}</strong>`:`<small>Series status</small><strong>${summitStandings(d)[0]?profileEscape(summitStandings(d)[0].name)+' • '+summitStandings(d)[0].points+' pts':'Opening round'}</strong>`}</div><button class="btn ${complete?'good':'primary'}" data-summit-disc="${d}">${complete?'VIEW RESULT':'START '+discLabel(d).toUpperCase()}</button></section>`}).join('')}</div>${m.completed?'<div style="margin-top:14px"><button id="backToSummitSeries" class="btn secondary">RETURN TO SUMMIT SERIES</button></div>':''}</div></div>`;document.querySelectorAll('[data-summit-disc]').forEach(b=>b.onclick=()=>{activeEventDisc=b.dataset.summitDisc;competitionMode='discipline';drawCompetition()});if($('simSummitRemaining'))$('simSummitRemaining').onclick=()=>{simulateSummitMeeting(m);competitionMode='overview';render()};if($('backToSummitSeries'))$('backToSummitSeries').onclick=()=>{summitLiveMeetingNumber=null;competitionMode='overview';view('league')}}
function drawSummitDisciplineLive(m){const d=activeEventDisc||Object.keys(DISCIPLINES)[0],rows=m.results[d]||null,running=disciplineRunning&&!rows,proxy=summitProxy(m),visual=rows||running?eventVisualHTML(proxy,d):summitReadyVisual(m,d),own=summitEntriesForDisc(m,d);$('pageKicker').textContent='SUMMIT SERIES';$('pageTitle').textContent='Series '+m.number+' • '+discLabel(d);$('competition').innerHTML=`<div class="comp-layout"><div class="stack"><section class="summit-live-discipline"><div class="summit-live-discipline-head"><div><small>SUMMIT SERIES ${m.number} • ${profileEscape(m.location)}</small><h2>${discLabel(d)}</h2></div><span>${rows?'Official Series result':running?'LIVE':'Ready'}</span></div><div id="liveEventVisual" class="summit-live-visual">${visual}</div><div id="commentary" class="commentary summit-live-commentary">${rows?profileEscape((m.commentary?.[d]||[commentaryResult(d,rows)]).join('\n\n')):running?profileEscape(liveEventView?.lines.slice(0,liveEventView.index+1).join('\n\n')||'Preparing the Summit field...'):`The ${discLabel(d)} field is ready.\n\nPress START DISCIPLINE when you are ready.`}</div></section></div><aside class="stack"><section class="panel"><div class="panel-h"><strong>Committed Entries</strong><span>Full Series roster</span></div>${own.length?own.map(a=>`<div class="entry-row"><div>${athleteLink(a)}<small>${a.injury>0?'Injured':`PB ${fmtPerf(a.disc,a.pb)} • Form ${a.form}`}</small></div><span class="status ${health(a)[1]}">${health(a)[0]}</span></div>`).join(''):'<div class="panel-body muted">No national athlete committed.</div>'}</section><section class="panel"><div class="panel-h"><strong>Summit Control</strong><span>Round ${m.number}/6</span></div><div class="panel-body stack"><button id="startSummitDisc" class="btn ${rows?'good':'primary'}" ${rows||disciplineRunning?'disabled':''}>${rows?'DISCIPLINE COMPLETE':disciplineRunning?'IN PROGRESS':'START DISCIPLINE'}</button><button id="backSummitProgramme" class="btn ghost">BACK TO SUMMIT PROGRAMME</button></div></section></aside></div>`;$('backSummitProgramme').onclick=()=>{competitionMode='overview';drawCompetition()};if($('startSummitDisc'))$('startSummitDisc').onclick=()=>startSummitDiscipline(m,d)}
function startSummitDiscipline(m,d){if(!m||m.completed||disciplineRunning||m.week!==s.game.week)return;if(Array.isArray(m.results[d]))return;const career=s,rows=summitRows(m,d),proxy=summitProxy(m),lines=commentaryLines(d,rows,proxy);disciplineRunning=true;m.eventDayMode='watch';m.commentary??={};m.commentary[d]=lines;liveEventView={event:proxy,disc:d,results:rows,lines,index:-1};drawCompetition();let i=0;function step(){if(s!==career)return;if(i<lines.length){liveEventView.index=i;const comm=$('commentary'),arena=$('liveEventVisual');if(comm){comm.textContent=lines.slice(0,i+1).join('\n\n');comm.scrollTop=comm.scrollHeight}if(arena)arena.innerHTML=eventVisualHTML(proxy,d);i++;timers.push(setTimeout(step,commentaryDelay(lines[i-1])));return}commitSummitRows(m,d,rows);disciplineRunning=false;liveEventView=null;if(Object.keys(DISCIPLINES).every(x=>Array.isArray(m.results[x])))finishSummitMeeting(m);save();if(m.completed){competitionMode='overview';render()}else drawCompetition()}step()}
const _summitNormalBlock=currentBlocking;
currentBlocking=function(){const normal=_summitNormalBlock();if(normal)return normal;const m=summitCurrentLiveMeeting();if(m){m.kind='summit';m.disc=Object.keys(DISCIPLINES);m.name='Summit Series '+m.number;m.level='Summit Series';return m}return null};
const _summitDrawCompetition=drawCompetition;
drawCompetition=function(){const normal=_summitNormalBlock();if(normal){summitLiveMeetingNumber=null;return _summitDrawCompetition()}let m=summitCurrentLiveMeeting();if(!m&&summitLiveMeetingNumber)m=summitSeasonState().meetings[summitLiveMeetingNumber];if(!m)return _summitDrawCompetition();summitLiveMeetingNumber=m.number;if(!m.completed&&!m.eventDayMode&&!Object.values(m.results||{}).some(Array.isArray)){drawSummitArrival(m);return}if(competitionMode==='discipline'){drawSummitDisciplineLive(m);return}drawSummitOverviewLive(m)};
const _summitRender=render;
render=function(){_summitRender();const block=currentBlocking(),career=careerState();if(block&&!appointmentPending()&&!career.finished&&!career.pendingReview){$('advanceTop').disabled=false;$('advanceTop').textContent=block.kind==='summit'?'ENTER SUMMIT EVENT':'ENTER EVENT'}};
