function trainingSubnavHTML(){return `<div class="training-subnav" role="tablist" aria-label="Training sections"><button type="button" class="${trainingTab==='programme'?'on':''}" data-training-section="programme" role="tab" aria-selected="${trainingTab==='programme'}">WEEKLY TRAINING</button><button type="button" class="${trainingTab==='camps'?'on':''}" data-training-section="camps" role="tab" aria-selected="${trainingTab==='camps'}">TRAINING CAMPS</button></div><p class="training-subnav-note">Weekly Training controls the squad's normal programme. Training Camps are longer blocks that reserve athletes and can conflict with competitions.</p>`}
