function broadcastFieldNotes(d,rows,e,own){const top=[...rows].slice(0,3),parts=[];if(top[0]){const a=s.athletes.find(x=>x.id===top[0].id);parts.push(`${top[0].name} owns a PB of ${a?fmtPerf(d,a.pb):fmtPerf(d,top[0].perf)}`)}if(own.length){const names=own.map(x=>x.name).join(own.length>1?' and ':', ');parts.push(`${nationName(managedNation())} ${own.length>1?'have':'has'} ${names} in this one`)}const rival=top[0]&&s.athletes.find(x=>x.id===top[0].id),pair=rival&&typeof activeRivalFor==='function'?activeRivalFor(rival):null;if(pair){const other=s.athletes.find(x=>pair.ids.includes(x.id)&&x.id!==rival.id);if(other&&rows.some(x=>x.id===other.id))parts.push(`${rival.name} and ${other.name} renew a familiar head-to-head`)}return parts.join('. ')+(parts.length?'.':'')}
function broadcastSprintLines(d,r,e,key){const rows=broadcastVisibleRows(d,r,e),winner=rows[0],second=rows[1],own=rows.filter(x=>(e.entries?.[d]||[]).includes(x.id)&&x.nation===managedNation()),watch=own[0]||winner,meta=e?.engine?.[d],close=second&&Math.abs(winner.perf-second.perf)<=.05,lane=x=>x?.lane?` in lane ${x.lane}`:'';const lines=[];lines.push(`ON YOUR MARKS\nGavin Potts — ${broadcastPick(['The stadium drops away to almost nothing now. Everyone is behind the blocks and waiting for the starter.','Listen to the noise disappear. This is the moment the talking stops — eight lanes, one straight, no second chances.','They settle behind the blocks. Shoulders loose, eyes down, and the whole field waiting on the same sound.'],key+'|marks')}`);lines.push(`SET… GO!\nGavin Potts — Set... and away they go! ${watch?`${watch.name}${lane(watch)} is into the drive phase`:'A clean break across the line'}, and nobody can afford to give much away here.`);lines.push(`20 METRES\nGavin Potts — ${watch?`${watch.name} is working hard through the first twenty, still low and powerful.`:'The field is still in the drive phase.'} ${winner&&winner.id!==watch?.id?`${winner.name} has made a very sharp beginning.`:''}`.trim());lines.push(`40 METRES\nGavin Potts — They are upright now and beginning to open the stride. ${winner&&second?`${winner.name} and ${second.name} are starting to come through the middle of the race.`:'This is where acceleration turns into top speed.'}`);lines.push(`60 METRES\nGavin Potts — ${winner&&second?(close?`${winner.name} and ${second.name} are almost level — this is very, very tight.`:`${winner.name} is beginning to get the better of ${second.name}, but there is still plenty of track left.`):`Maximum velocity now. It is about holding shape and refusing to tighten.`}`);lines.push(`80 METRES\nGavin Potts — ${winner&&second?(close?`Still nothing in it! ${winner.name}, ${second.name}, both reaching for the line now.`:`${winner.name} has the advantage. ${second.name} is trying to come back, twenty metres to find something.`):`${winner?.name||'The leader'} is driving all the way through the line.`}`);lines.push(`100 METRES • THE LINE\nGavin Potts — ${winner&&second?(close?`They hit it together! ${winner.name} and ${second.name} — do not call that from the naked eye. We wait for the clock.`:`${winner.name} gets there! A clear run through the line, and the clock is coming up now.`):`${winner?.name||'The field'} is through the finish.`}`);return lines}
