function attemptHighJumpVisual(e,d,rows,cue){
 const row=rows.find(r=>r.id===cue.athleteId)||rows[0],watch=row,phase={stage:cue.outcome==='-'?'apron':'flight'},svg=highJumpBroadcastVisual(rows,phase,true,1.65,watch),label=cue.outcome==='O'?'CLEAR':cue.outcome==='X'?'MISS':'PASS',tone=cue.outcome==='O'?'good':cue.outcome==='X'?'bad':'';
 return `<div class="live-arena"><div class="live-arena-head"><span>${fmtPerf(d,cue.height)} • ${profileEscape(row.name)} • ${cue.attempt?`Attempt ${cue.attempt}`:'Pass'}</span></div><div class="live-arena-stage" style="position:relative"><div class="attempt-visual-score"><small>High Jump</small><strong>${profileEscape(row.name)}</strong><span>${fmtPerf(d,cue.height)}${cue.attempt?' • attempt '+cue.attempt:''}</span></div><div class="attempt-visual-result ${tone}">${label}</div>${svg}</div><div class="live-arena-legend"><span><i style="background:${nationDotColour(row.nation)}"></i>${profileEscape(row.name)} · ${label.toLowerCase()} at ${fmtPerf(d,cue.height)}</span></div></div>`;
}
const _attemptBaseVisual=eventVisualHTML;
eventVisualHTML=function(e,d){
 const active=liveEventView?.event===e&&liveEventView?.disc===d?liveEventView:null,line=active?.lines?.[active.index],cue=line&&e?.engine?.[d]?.broadcastCues?.[line];
 if(cue?.family==='throws')return attemptShotPutVisual(e,d,active.results,cue);
 if(cue?.family==='height')return attemptHighJumpVisual(e,d,active.results,cue);
 return _attemptBaseVisual(e,d);
};

const _attemptBaseSummitProxy=summitProxy;
summitProxy=function(m){const p=_attemptBaseSummitProxy(m);p.engine=m.engine||p.engine||{};return p};
const _attemptBaseSummitRows=summitRows;
summitRows=function(m,d){
 const base=_attemptBaseSummitRows(m,d),proxy=summitProxy(m),out=athleticsRunEngine(proxy,d,base.map(r=>({...r})));m.engine??={};m.engine[d]=out.meta;proxy.engine??={};proxy.engine[d]=out.meta;return out.rows;
};

function emailInitials(senderName){const words=String(senderName||'AM').replace(/[^A-Za-z0-9 ]/g,' ').trim().split(/\s+/).filter(Boolean);return (words.slice(0,2).map(x=>x[0]).join('')||'AM').toUpperCase()}
const _emailPolishDrawReader=drawReader;
drawReader=function(){
 _emailPolishDrawReader();const el=$('reader'),m=s.emails.find(x=>x.id===openMail)||s.emails[s.emails.length-1];if(!el||!m)return;el.classList.add('email-reader');const head=el.querySelector('.reader-head');if(!head)return;
 const recipient=`${nationName(managedNation())} Performance Director`;
 head.innerHTML=`${mailTypeHTML(m)}<div class="email-message-top"><div class="email-avatar">${profileEscape(emailInitials(m.sender))}</div><div class="email-sender"><strong>${profileEscape(m.sender)}</strong><span>to ${profileEscape(recipient)}</span></div><div class="email-date">Year ${m.year}<br>Week ${m.week}</div></div><h2>${profileEscape(m.subject)}</h2><div class="email-header-meta"><span><strong>From:</strong> ${profileEscape(m.sender)}</span><span><strong>To:</strong> ${profileEscape(recipient)}</span></div>`;
};

UPDATES.unshift({date:'8 September 2026',title:'Event Finish, Attempt Playback & Email Polish',items:['Completed meetings now present an active Complete Event button that exits Event Day and returns directly to the main game instead of leaving the player trapped inside the full-screen match view.','Shot Put now plays the actual Athletics Engine attempt series rather than one generic throw. Every valid throw or foul Gavin calls is shown as its own attempt, and the visual landing measurement uses the exact distance from the commentary.','High Jump now follows the same attempt-by-attempt principle, showing each pass, miss and clearance at the correct height so the animation and commentary describe the same competition sequence. Summit Series field events use the same multi-attempt engine.','Inbox messages have been redesigned to resemble real emails, with a proper sender/recipient header, stronger subject hierarchy, clearer metadata and significantly larger body copy. Embedded selection tools remain distinct inside the message.']});
{const latestIndex=UPDATES.findIndex(u=>u.title==='Event Finish, Attempt Playback & Email Polish');if(latestIndex>0)UPDATES.unshift(UPDATES.splice(latestIndex,1)[0]);}
if(typeof renderMenu==='function')renderMenu();
