/* ===== Selection submission lock ===== */
function selectionSubmissionSnapshot(e){
 if(!e)return [];
 return e.disc.filter(d=>d!=='ALL').map(d=>({disc:d,names:(e.entries?.[d]||[]).map(id=>s.athletes.find(a=>a.id===id)?.name).filter(Boolean)})).filter(x=>x.names.length)
}
function summitSubmissionSnapshot(){
 const ss=summitSeasonState();return Object.keys(DISCIPLINES).map(d=>({disc:d,names:(ss.seriesEntries||[]).map(id=>s.athletes.find(a=>a.id===id)).filter(a=>a&&a.disc===d).map(a=>a.name)})).filter(x=>x.names.length)
}
function lockSelectionMail(mail,snapshot,label='Selection submitted'){
 if(!mail)return;
 mail.selectionSubmitted=true;mail.selectionSubmittedSeason=s.game.season;mail.selectionSubmittedWeek=s.game.week;mail.selectionSubmittedLabel=label;mail.selectionSubmittedSnapshot=snapshot||[];save()
}
function selectionSubmittedHTML(m){
 const rows=m.selectionSubmittedSnapshot||[];const detail=rows.length?rows.map(x=>`${discLabel(x.disc)}: ${x.names.join(', ')}`).join(' • '):'No athletes selected.';
 return `<div class="selection-submitted-banner"><small>Decision locked</small><strong>${profileEscape(m.selectionSubmittedLabel||'Selection submitted')}</strong><p>${profileEscape(detail)} This email is now read-only.</p></div>`
}
const _submissionLockConfirmEventSelection=confirmEventSelection;
confirmEventSelection=function(e){
 const mail=s.emails.find(x=>x.id===openMail);
 const ok=_submissionLockConfirmEventSelection(e);
 if(ok&&mail?.type==='selection'&&mail.eventId===e.id)lockSelectionMail(mail,selectionSubmissionSnapshot(e),'Event selection submitted');
 return ok
};
const _submissionLockApplyRecommendedSummit=applyRecommendedSummitSelection;
applyRecommendedSummitSelection=function(){
 const mail=s.emails.find(x=>x.id===openMail),ok=_submissionLockApplyRecommendedSummit();
 if(ok&&mail?.summitRegistration){lockSelectionMail(mail,summitSubmissionSnapshot(),'Summit Series team submitted');toast('Recommended Summit team selected and submitted');drawReader()}
 return ok
};
const _submissionLockDrawReader=drawReader;
drawReader=function(){
 _submissionLockDrawReader();
 const reader=$('reader'),m=s.emails.find(x=>x.id===openMail)||s.emails[s.emails.length-1];if(!reader||!m)return;
 const e=m.eventId?s.events.find(x=>x.id===m.eventId):null;
 if(!m.summitRegistration&&m.type==='selection'&&e?.decision&&!m.selectionSubmitted)lockSelectionMail(m,selectionSubmissionSnapshot(e),'Event selection submitted');
 const submitted=!!m.selectionSubmitted;
 if(!submitted){
   if(e&&$('confirmSelection'))$('confirmSelection').onclick=()=>confirmEventSelection(e);
   if($('selectAllRecommended'))$('selectAllRecommended').onclick=()=>applyRecommendedEventSelection(e);
   if($('selectAllSummitRecommended'))$('selectAllSummitRecommended').onclick=()=>applyRecommendedSummitSelection();
   return
 }
 const body=reader.querySelector('.reader-body');if(body&&!body.querySelector('.selection-submitted-banner'))body.insertAdjacentHTML('afterbegin',selectionSubmittedHTML(m));
 const box=reader.querySelector('.selection-box');if(box)box.classList.add('submitted');
 reader.querySelectorAll('.select-toggle,[data-sel],[data-selection-reason],#confirmSelection,#selectAllRecommended,#selectAllSummitRecommended,[data-open-summit-registration],#openEvent').forEach(el=>el.remove());
 const actions=reader.querySelector('.reader-actions');if(actions)actions.innerHTML='';
};
